// 00_hello_dojo / ex1 - reference solution.

export function Greeting({ name }: { name: string }) {
  return <h1>Hello, {name}! Welcome to the dojo.</h1>;
}

// 00_hello_dojo / ex2 - reference solution.

export function TrackSummary({ track, lessons }: { track: string; lessons: number }) {
  const noun = lessons === 1 ? "lesson" : "lessons";
  return (
    <p>
      {track}: {lessons} {noun}
    </p>
  );
}

// 00_hello_dojo / ex3 - reference solution.

export function IconButton({
  label,
  glyph,
  onPress,
}: {
  label: string;
  glyph: string;
  onPress: () => void;
}) {
  return (
    <button type="button" aria-label={label} onClick={onPress}>
      {glyph}
    </button>
  );
}

// 01_components_jsx / challenge - reference solution.

export function Crumb({
  label,
  href,
  current,
}: {
  label: string;
  href: string;
  current: boolean;
}) {
  if (current) {
    return <span aria-current="page">{label}</span>;
  }
  return <a href={href}>{label}</a>;
}

// 01_components_jsx / ex1 - reference solution.

export function PageHeader({ title, subtitle }: { title: string; subtitle: string }) {
  return (
    <header>
      <h1>{title}</h1>
      <p>{subtitle}</p>
    </header>
  );
}

// 01_components_jsx / ex2 - reference solution.

export function ProfileLink({ name, href }: { name: string; href: string }) {
  return <a href={href}>Open {name}</a>;
}

// 01_components_jsx / ex3 - reference solution.

export function LabelledField({ label, value }: { label: string; value: string }) {
  return (
    <>
      <dt>{label}</dt>
      <dd>{value}</dd>
    </>
  );
}

// 01_components_jsx / ex4 - reference solution.

export function Notice({ tone, message }: { tone: "error" | "info"; message: string }) {
  const role = tone === "error" ? "alert" : "status";
  return (
    <p role={role} className={`notice notice-${tone}`}>
      {message}
    </p>
  );
}

// 01_components_jsx / review1 - reference solution.

export function Field({ id, label, hint }: { id: string; label: string; hint: string }) {
  const hintId = `${id}-hint`;
  return (
    <>
      <label htmlFor={id}>{label}</label>
      <input id={id} aria-describedby={hintId} />
      <span id={hintId}>{hint}</span>
    </>
  );
}

// 02_props_composition / challenge - reference solution.
import { useId } from "react";
import type { ReactNode } from "react";

export function Modal({
  title,
  children,
  onClose,
}: {
  title: string;
  children: ReactNode;
  onClose: () => void;
}) {
  const titleId = useId();
  return (
    <div role="dialog" aria-modal="true" aria-labelledby={titleId}>
      <h2 id={titleId}>{title}</h2>
      {children}
      <button type="button" onClick={onClose}>
        Close
      </button>
    </div>
  );
}

// 02_props_composition / ex1 - reference solution.
import type { ReactNode } from "react";

export function Card({ title, children }: { title: string; children: ReactNode }) {
  return (
    <article>
      <h3>{title}</h3>
      {children}
    </article>
  );
}

// 02_props_composition / ex2 - reference solution.

export function Rating({ value, max = 5 }: { value: number; max?: number }) {
  return (
    <span role="img" aria-label={`${value} out of ${max} stars`}>
      {"★".repeat(value)}
      {"☆".repeat(max - value)}
    </span>
  );
}

// 02_props_composition / ex3 - reference solution.
import type { ReactNode } from "react";

export function Panel({
  header,
  footer,
  children,
}: {
  header: ReactNode;
  footer: ReactNode;
  children: ReactNode;
}) {
  return (
    <section>
      <div className="panel-header">{header}</div>
      <div className="panel-body">{children}</div>
      <div className="panel-footer">{footer}</div>
    </section>
  );
}

// 02_props_composition / ex4 - reference solution.
import type { ComponentProps } from "react";

type TextFieldProps = { label: string; id: string } & ComponentProps<"input">;

export function TextField({ label, id, ...rest }: TextFieldProps) {
  return (
    <>
      <label htmlFor={id}>{label}</label>
      <input id={id} {...rest} />
    </>
  );
}

// 02_props_composition / review1 - reference solution.
import type { ReactNode } from "react";

export function MediaObject({ media, children }: { media: ReactNode; children: ReactNode }) {
  return (
    <div className="media">
      <div className="media-figure">{media}</div>
      <div className="media-body">{children}</div>
    </div>
  );
}

