// 03_state_events / challenge - reference solution.
import { useState } from "react";

export function UndoableCounter() {
  const [history, setHistory] = useState<number[]>([0]);
  const count = history[history.length - 1];

  function push(next: (current: number) => number) {
    setHistory((previous) => [...previous, next(previous[previous.length - 1])]);
  }

  return (
    <>
      <output>{count}</output>
      <button type="button" onClick={() => push((n) => n + 1)}>
        Increment
      </button>
      <button type="button" onClick={() => push((n) => n - 1)}>
        Decrement
      </button>
      <button
        type="button"
        disabled={history.length === 1}
        onClick={() => setHistory((previous) => previous.slice(0, -1))}
      >
        Undo
      </button>
    </>
  );
}

// 03_state_events / ex1 - reference solution.
import { useState } from "react";

export function Counter() {
  const [count, setCount] = useState(0);

  return (
    <>
      <output>{count}</output>
      <button type="button" onClick={() => setCount(count + 1)}>
        Increment
      </button>
    </>
  );
}

// 03_state_events / ex2 - reference solution.
import { useState } from "react";

export function DoubleTap() {
  const [count, setCount] = useState(0);

  function handleClick() {
    setCount((previous) => previous + 1);
    setCount((previous) => previous + 1);
  }

  return (
    <>
      <output>{count}</output>
      <button type="button" onClick={handleClick}>
        Add two
      </button>
    </>
  );
}

// 03_state_events / ex3 - reference solution.
import { useState } from "react";

export function LikeButton() {
  const [liked, setLiked] = useState(false);

  return (
    <button type="button" aria-pressed={liked} onClick={() => setLiked((was) => !was)}>
      Like
    </button>
  );
}

// 03_state_events / ex4 - reference solution.
import { useState } from "react";

export function BatchProbe({ onRender }: { onRender: () => void }) {
  const [a, setA] = useState(0);
  const [b, setB] = useState(0);
  const [c, setC] = useState(0);

  onRender();

  function handleClick() {
    setA((previous) => previous + 1);
    setB((previous) => previous + 1);
    setC((previous) => previous + 1);
  }

  return (
    <>
      <output>
        {a}-{b}-{c}
      </output>
      <button type="button" onClick={handleClick}>
        Bump all
      </button>
    </>
  );
}

// 03_state_events / review1 - reference solution.
import { useState } from "react";

export function Thermostat({ min, max }: { min: number; max: number }) {
  const [temperature, setTemperature] = useState(min);

  function shift(by: number) {
    setTemperature((previous) => Math.min(max, Math.max(min, previous + by)));
  }

  return (
    <>
      <output>{temperature}&deg;C</output>
      <button type="button" onClick={() => shift(1)}>
        Warmer
      </button>
      <button type="button" onClick={() => shift(-1)}>
        Cooler
      </button>
    </>
  );
}

// 04_lists_conditional / challenge - reference solution.

type Status = "todo" | "doing" | "done";
type Task = { id: string; title: string; status: Status };

export const GROUPS: { status: Status; label: string }[] = [
  { status: "todo", label: "To do" },
  { status: "doing", label: "Doing" },
  { status: "done", label: "Done" },
];

export function GroupedTasks({ tasks }: { tasks: Task[] }) {
  return (
    <>
      {GROUPS.map(({ status, label }) => {
        const inGroup = tasks
          .filter((task) => task.status === status)
          .sort((a, b) => a.title.localeCompare(b.title));

        if (inGroup.length === 0) {
          return null;
        }

        return (
          <section key={status}>
            <h3>{label}</h3>
            <ul>
              {inGroup.map((task) => (
                <li key={task.id}>{task.title}</li>
              ))}
            </ul>
          </section>
        );
      })}
    </>
  );
}

// 04_lists_conditional / ex1 - reference solution.

export function TagList({ tags }: { tags: string[] }) {
  return (
    <ul>
      {tags.map((tag) => (
        <li key={tag}>{tag}</li>
      ))}
    </ul>
  );
}

// 04_lists_conditional / ex2 - reference solution.
import { useState } from "react";

type Person = { id: string; name: string };

export function PeopleList({
  initialPeople,
  newcomer,
}: {
  initialPeople: Person[];
  newcomer: Person;
}) {
  const [people, setPeople] = useState(initialPeople);

  return (
    <>
      <button type="button" onClick={() => setPeople((previous) => [newcomer, ...previous])}>
        Add to front
      </button>
      <ul>
        {people.map((person) => (
          <li key={person.id}>
            <label htmlFor={person.id}>{person.name}</label>
            <input id={person.id} defaultValue="" />
          </li>
        ))}
      </ul>
    </>
  );
}

// 04_lists_conditional / ex3 - reference solution.

type Message = { id: string; subject: string };

export function Inbox({
  messages,
  unreadCount,
}: {
  messages: Message[];
  unreadCount: number;
}) {
  if (messages.length === 0) {
    return <p>No messages</p>;
  }

  return (
    <>
      {unreadCount > 0 && <span>{unreadCount} unread</span>}
      <ul>
        {messages.map((message) => (
          <li key={message.id}>{message.subject}</li>
        ))}
      </ul>
    </>
  );
}

// 04_lists_conditional / ex4 - reference solution.

type Player = { name: string; score: number };

export function Leaderboard({ players }: { players: Player[] }) {
  const top = [...players]
    .sort((a, b) => b.score - a.score || a.name.localeCompare(b.name))
    .slice(0, 3);

  return (
    <ol>
      {top.map((player) => (
        <li key={player.name}>
          {player.name}: {player.score}
        </li>
      ))}
    </ol>
  );
}

// 04_lists_conditional / review1 - reference solution.
import { useState } from "react";

type Chip = { id: string; label: string };

export function Chips({ items }: { items: Chip[] }) {
  const [chips, setChips] = useState(items);

  function remove(id: string) {
    setChips((previous) => previous.filter((chip) => chip.id !== id));
  }

  return (
    <ul>
      {chips.map((chip) => (
        <li key={chip.id}>
          <button type="button" onClick={() => remove(chip.id)}>
            Remove {chip.label}
          </button>
        </li>
      ))}
    </ul>
  );
}

