}

// 05_forms / ex2 - reference solution.
import { useState } from "react";

export function Preferences() {
  const [theme, setTheme] = useState("light");
  const [emails, setEmails] = useState(false);

  return (
    <>
      <label htmlFor="theme">Theme</label>
      <select id="theme" value={theme} onChange={(event) => setTheme(event.target.value)}>
        <option value="light">Light</option>
        <option value="dark">Dark</option>
        <option value="system">System</option>
      </select>

      <input
        id="emails"
        type="checkbox"
        checked={emails}
        onChange={(event) => setEmails(event.target.checked)}
      />
      <label htmlFor="emails">Email me updates</label>

      <output>
        Theme: {theme}, emails {emails ? "on" : "off"}
      </output>
    </>
  );
}

// 05_forms / ex3 - reference solution.
import { useState } from "react";

export function SignupForm() {
  const [form, setForm] = useState({ name: "", email: "" });

  function handleChange(event: React.ChangeEvent<HTMLInputElement>) {
    const { name, value } = event.target;
    setForm((previous) => ({ ...previous, [name]: value }));
  }

  return (
    <>
      <label htmlFor="name">Name</label>
      <input id="name" name="name" value={form.name} onChange={handleChange} />

      <label htmlFor="email">Email</label>
      <input id="email" name="email" value={form.email} onChange={handleChange} />

      <output>
        {form.name} &lt;{form.email}&gt;
      </output>
    </>
  );
}

// 05_forms / ex4 - reference solution.
import { useState } from "react";

function validate(email: string, password: string): string[] {
  const problems: string[] = [];
  if (!email.includes("@")) {
    problems.push("Enter a valid email address");
  }
  if (password.length < 8) {
    problems.push("Password must be at least 8 characters");
  }
  return problems;
}

export function LoginForm({
  onSubmit,
}: {
  onSubmit: (credentials: { email: string; password: string }) => void;
}) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [problems, setProblems] = useState<string[]>([]);

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const found = validate(email, password);
    setProblems(found);
    if (found.length === 0) {
      onSubmit({ email, password });
    }
  }

  return (
    <form onSubmit={handleSubmit}>
      <label htmlFor="email">Email</label>
      <input id="email" value={email} onChange={(event) => setEmail(event.target.value)} />

      <label htmlFor="password">Password</label>
      <input
        id="password"
        type="password"
        value={password}
        onChange={(event) => setPassword(event.target.value)}
      />

      {problems.length > 0 && (
        <ul role="alert">
          {problems.map((problem) => (
            <li key={problem}>{problem}</li>
          ))}
        </ul>
      )}

      <button type="submit">Sign in</button>
    </form>
  );
}

// 05_forms / review1 - reference solution.
import { useState } from "react";

export function NewsletterForm({ onSubscribe }: { onSubscribe: (email: string) => void }) {
  const [email, setEmail] = useState("");
  const [agreed, setAgreed] = useState(false);
  const ready = email.trim() !== "" && agreed;

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        onSubscribe(email);
      }}
    >
      <label htmlFor="news-email">Email</label>
      <input id="news-email" value={email} onChange={(event) => setEmail(event.target.value)} />

      <input
        id="news-agree"
        type="checkbox"
        checked={agreed}
        onChange={(event) => setAgreed(event.target.checked)}
      />
      <label htmlFor="news-agree">I agree to the terms</label>

      <button type="submit" disabled={!ready}>
        Subscribe
      </button>
    </form>
  );
}

