// 06_effects / challenge - reference solution.
import { useEffect, useState } from "react";

export function Stopwatch() {
  const [seconds, setSeconds] = useState(0);
  const [running, setRunning] = useState(false);

  useEffect(() => {
    if (!running) {
      return;
    }
    const id = setInterval(() => {
      setSeconds((previous) => previous + 1);
    }, 1000);
    return () => clearInterval(id);
  }, [running]);

  return (
    <>
      <output>{seconds}</output>
      <button type="button" onClick={() => setRunning(true)}>
        Start
      </button>
      <button type="button" onClick={() => setRunning(false)}>
        Stop
      </button>
    </>
  );
}

exercises.importantHints:
## Hint 1
`document.title` is not part of React's tree, so setting it is a *side effect* —
something that reaches outside the component. Side effects do not belong in the
render body; they belong in `useEffect`, which React runs after the DOM has
been updated.

## Hint 2
```tsx
useEffect(() => {
  // set it
  return () => {
    // put it back
  };
}, [/* what this effect reads */]);
```

Three parts, all required here: the body, the cleanup it returns, and the
dependency list saying when to run again.

## Hint 3
The cleanup has to restore *the title as it was before this effect ran*, so
capture it inside the effect body before overwriting — a `const` at the top of
the effect closes over exactly the right value, because each run of the effect
gets its own. The remaining decision is the dependency array; the gate
re-renders with a new title and expects the document to follow.

references.solution.tsx:
// 06_effects / ex1 - reference solution.
import { useEffect } from "react";

export function PageTitle({ title }: { title: string }) {
  useEffect(() => {
    const previous = document.title;
    document.title = title;
    return () => {
      document.title = previous;
    };
  }, [title]);

  return null;
}

// 06_effects / ex2 - reference solution.
import { useEffect } from "react";

export function ThemeSync({
  theme,
  onSync,
  label,
}: {
  theme: string;
  onSync: (theme: string) => void;
  label: string;
}) {
  useEffect(() => {
    onSync(theme);
  }, [theme, onSync]);

  return <p>{label}</p>;
}

// 06_effects / ex3 - reference solution.
import { useEffect } from "react";

export function EscapeToClose({ onClose }: { onClose: () => void }) {
  useEffect(() => {
    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") {
        onClose();
      }
    }

    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [onClose]);

  return <p>Press Escape to close</p>;
}

// 06_effects / ex4 - reference solution.
import { useEffect, useState } from "react";

type User = { name: string };

export function UserBadge({
  userId,
  fetchUser,
}: {
  userId: string;
  fetchUser: (id: string) => Promise<User>;
}) {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    let cancelled = false;
    fetchUser(userId).then((result) => {
      if (!cancelled) {
        setUser(result);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [userId, fetchUser]);

  return <p>{user === null ? "" : user.name}</p>;
}

// 06_effects / review1 - reference solution.
import { useEffect } from "react";

export function AnnounceOnChange({
  message,
  onAnnounce,
  onClear,
}: {
  message: string;
  onAnnounce: (message: string) => void;
  onClear: (message: string) => void;
}) {
  useEffect(() => {
    onAnnounce(message);
    return () => {
      onClear(message);
    };
  }, [message, onAnnounce, onClear]);

  return <p role="status">{message}</p>;
}

