import { createContext, useContext } from "react";
import type { ReactNode } from "react";

const ThemeContext = createContext("light");

export function ThemeProvider({ theme, children }: { theme: string; children: ReactNode }) {
  return <ThemeContext.Provider value={theme}>{children}</ThemeContext.Provider>;
}

export function ThemedButton() {
  const theme = useContext(ThemeContext);
  return <button type="button">Theme: {theme}</button>;
}

// 09_context_reducer / ex2 - reference solution.
import { createContext, useContext } from "react";
import type { ReactNode } from "react";

const SettingsContext = createContext<string | null>(null);

export function SettingsProvider({
  density,
  children,
}: {
  density: string;
  children: ReactNode;
}) {
  return <SettingsContext.Provider value={density}>{children}</SettingsContext.Provider>;
}

export function useSettings(): string {
  const value = useContext(SettingsContext);
  if (value === null) {
    throw new Error("useSettings must be used inside a SettingsProvider");
  }
  return value;
}

export function Density() {
  const density = useSettings();
  return <p role="status">Density: {density}</p>;
}

// 09_context_reducer / ex3 - reference solution.

export type CartItem = { id: string; name: string; price: number; quantity: number };

export type CartAction =
  | { type: "added"; id: string; name: string; price: number }
  | { type: "removed"; id: string }
  | { type: "quantitySet"; id: string; quantity: number }
  | { type: "cleared" };

export function cartReducer(state: CartItem[], action: CartAction): CartItem[] {
  switch (action.type) {
    case "added": {
      const existing = state.find((item) => item.id === action.id);
      if (existing) {
        return state.map((item) =>
          item.id === action.id ? { ...item, quantity: item.quantity + 1 } : item,
        );
      }
      return [...state, { id: action.id, name: action.name, price: action.price, quantity: 1 }];
    }
    case "removed":
      return state.filter((item) => item.id !== action.id);
    case "quantitySet":
      if (action.quantity <= 0) {
        return state.filter((item) => item.id !== action.id);
      }
      return state.map((item) =>
        item.id === action.id ? { ...item, quantity: action.quantity } : item,
      );
    case "cleared":
      return [];
    default:
      return state;
  }
}

// 09_context_reducer / ex4 - reference solution.
import { useReducer, useState } from "react";

export type Task = { id: number; text: string; done: boolean };
export type TaskState = { tasks: Task[]; nextId: number };
export type TaskAction = { type: "added"; text: string } | { type: "toggled"; id: number };

export const initialTasks: TaskState = { tasks: [], nextId: 1 };

export function tasksReducer(state: TaskState, action: TaskAction): TaskState {
  switch (action.type) {
    case "added":
      return {
        tasks: [...state.tasks, { id: state.nextId, text: action.text, done: false }],
        nextId: state.nextId + 1,
      };
    case "toggled":
      return {
        ...state,
        tasks: state.tasks.map((task) =>
          task.id === action.id ? { ...task, done: !task.done } : task,
        ),
      };
    default:
      return state;
  }
}

export function TaskList() {
  const [state, dispatch] = useReducer(tasksReducer, initialTasks);
  const [draft, setDraft] = useState("");

  const done = state.tasks.filter((task) => task.done).length;

  function add() {
    if (draft.trim() === "") {
      return;
    }
    dispatch({ type: "added", text: draft });
    setDraft("");
  }

  return (
    <>
      <label htmlFor="new-task">New task</label>
      <input id="new-task" value={draft} onChange={(event) => setDraft(event.target.value)} />
      <button type="button" onClick={add}>
        Add
      </button>

      <ul>
        {state.tasks.map((task) => (
          <li key={task.id}>
            <input
              id={`task-${task.id}`}
              type="checkbox"
              checked={task.done}
              onChange={() => dispatch({ type: "toggled", id: task.id })}
            />
            <label htmlFor={`task-${task.id}`}>{task.text}</label>
          </li>
        ))}
      </ul>

      <p role="status">
        {done} of {state.tasks.length} done
      </p>
    </>
  );
}

