// 10_custom_hooks / challenge - reference solution.
import { useCallback, useEffect, useState } from "react";

export type AsyncState<T> = {
  status: "loading" | "success" | "error";
  data: T | null;
  error: string | null;
  reload: () => void;
};

export function useAsync<T>(run: () => Promise<T>): AsyncState<T> {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [status, setStatus] = useState<"loading" | "success" | "error">("loading");
  const [attempt, setAttempt] = useState(0);

  const reload = useCallback(() => {
    setAttempt((previous) => previous + 1);
  }, []);

  useEffect(() => {
    let current = true;
    setStatus("loading");
    setError(null);

    run()
      .then((result) => {
        if (!current) {
          return;
        }
        setData(result);
        setStatus("success");
      })
      .catch((problem: unknown) => {
        if (!current) {
          return;
        }
        setError(problem instanceof Error ? problem.message : "Something went wrong");
        setStatus("error");
      });

    return () => {
      current = false;
    };
  }, [run, attempt]);

  return { status, data, error, reload };
}

// 10_custom_hooks / ex1 - reference solution.
import { useCallback, useState } from "react";

export function useToggle(
  initial = false,
): [boolean, () => void, (value: boolean) => void] {
  const [on, setOn] = useState(initial);

  const toggle = useCallback(() => {
    setOn((previous) => !previous);
  }, []);

  return [on, toggle, setOn];
}

// 10_custom_hooks / ex2 - reference solution.
import { useCallback, useState } from "react";

export function useLocalStorage<T>(key: string, initialValue: T): [T, (value: T) => void] {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    if (stored === null) {
      return initialValue;
    }
    try {
      return JSON.parse(stored) as T;
    } catch {
      return initialValue;
    }
  });

  const store = useCallback(
    (next: T) => {
      setValue(next);
      localStorage.setItem(key, JSON.stringify(next));
    },
    [key],
  );

  return [value, store];
}

// 10_custom_hooks / ex3 - reference solution.
import { useEffect, useState } from "react";

export function useDebouncedValue<T>(value: T, delay: number): T {
  const [debounced, setDebounced] = useState(value);

  useEffect(() => {
    const id = setTimeout(() => {
      setDebounced(value);
    }, delay);

    return () => {
      clearTimeout(id);
    };
  }, [value, delay]);

  return debounced;
}

// 10_custom_hooks / ex4 - reference solution.
import { useId, useState } from "react";

export function VisitorPanel({ signedIn }: { signedIn: boolean }) {
  const headingId = useId();
  const [claps, setClaps] = useState(0);

  if (!signedIn) {
    return <p>Please sign in</p>;
  }

  return (
    <section aria-labelledby={headingId}>
      <h2 id={headingId}>Your claps</h2>
      <output>{claps} claps</output>
      <button type="button" onClick={() => setClaps((previous) => previous + 1)}>
        Clap
      </button>
    </section>
  );
}

