// 11_performance_patterns / challenge - reference solution.
import { memo, useMemo, useState } from "react";

export type Product = { id: string; name: string };

const Row = memo(function Row({
  product,
  onRowRender,
}: {
  product: Product;
  onRowRender: (id: string) => void;
}) {
  onRowRender(product.id);
  return <li>{product.name}</li>;
});

export function ProductTable({
  products,
  onRowRender,
}: {
  products: Product[];
  onRowRender: (id: string) => void;
}) {
  const [filter, setFilter] = useState("");

  const visible = useMemo(() => {
    const needle = filter.toLowerCase();
    return products
      .filter((product) => product.name.toLowerCase().includes(needle))
      .sort((a, b) => a.name.localeCompare(b.name));
  }, [products, filter]);

  return (
    <>
      <label htmlFor="filter">Filter</label>
      <input id="filter" value={filter} onChange={(event) => setFilter(event.target.value)} />

      <ul>
        {visible.map((product) => (
          <Row key={product.id} product={product} onRowRender={onRowRender} />
        ))}
      </ul>

      <p role="status">
        {visible.length} of {products.length} shown
      </p>
    </>
  );
}

// 11_performance_patterns / ex1 - reference solution.
import { memo } from "react";

export const ExpensiveRow = memo(function ExpensiveRow({
  label,
  onRender,
}: {
  label: string;
  onRender: () => void;
}) {
  onRender();
  return <li>{label}</li>;
});

// 11_performance_patterns / ex2 - reference solution.
import { memo, useCallback, useState } from "react";

const Child = memo(function Child({
  onSelect,
  onChildRender,
}: {
  onSelect: (value: string) => void;
  onChildRender: () => void;
}) {
  onChildRender();
  return (
    <button type="button" onClick={() => onSelect("apple")}>
      Pick
    </button>
  );
});

export function Parent({ onChildRender }: { onChildRender: () => void }) {
  const [clicks, setClicks] = useState(0);
  const [picked, setPicked] = useState("nothing");

  const handleSelect = useCallback((value: string) => {
    setPicked(value);
  }, []);

  return (
    <>
      <output>
        {clicks} clicks, picked {picked}
      </output>
      <button type="button" onClick={() => setClicks((previous) => previous + 1)}>
        Bump
      </button>
      <Child onSelect={handleSelect} onChildRender={onChildRender} />
    </>
  );
}

// 11_performance_patterns / ex3 - reference solution.
import { useMemo, useState } from "react";

export function Report({
  rows,
  compute,
}: {
  rows: number[];
  compute: (rows: number[]) => number;
}) {
  const [open, setOpen] = useState(false);

  const total = useMemo(() => compute(rows), [rows, compute]);

  return (
    <>
      <output>Total: {total}</output>
      <button type="button" onClick={() => setOpen((previous) => !previous)}>
        Toggle details
      </button>
      {open && <p>{rows.length} rows</p>}
    </>
  );
}

// 11_performance_patterns / ex4 - reference solution.
import { useState } from "react";

function ExpensiveList({ onExpensiveRender }: { onExpensiveRender: () => void }) {
  onExpensiveRender();
  return (
    <ul>
      <li>Everything</li>
      <li>Else</li>
    </ul>
  );
}

// The note's state now lives with the only things that use it, so typing
// re-renders NoteField and nothing else.
function NoteField() {
  const [note, setNote] = useState("");

  return (
    <>
      <label htmlFor="note">Note</label>
      <input id="note" value={note} onChange={(event) => setNote(event.target.value)} />
      <output>{note}</output>
    </>
  );
}

export function Dashboard({ onExpensiveRender }: { onExpensiveRender: () => void }) {
  return (
    <>
      <NoteField />
      <ExpensiveList onExpensiveRender={onExpensiveRender} />
    </>
  );
}

