// d01_jsx_rendering / ex1 - reference solution.

export function PriceTag({ label, cents }: { label: string; cents: number }) {
  return (
    <p>
      {label} - ${(cents / 100).toFixed(2)}
    </p>
  );
}

// d01_jsx_rendering / ex2 - reference solution.

export function Thumbnail({ src, alt, caption }: { src: string; alt: string; caption: string }) {
  return (
    <figure>
      <img src={src} alt={alt} />
      <figcaption>{caption}</figcaption>
    </figure>
  );
}

// d01_jsx_rendering / ex3 - reference solution.

export function Byline({
  author,
  isoDate,
  human,
}: {
  author: string;
  isoDate: string;
  human: string;
}) {
  return (
    <>
      <span>By {author}</span>
      <time dateTime={isoDate}>{human}</time>
    </>
  );
}

// d01_jsx_rendering / ex4 - reference solution.

export function ProgressMeter({
  label,
  done,
  total,
}: {
  label: string;
  done: number;
  total: number;
}) {
  const percent = total === 0 ? 0 : Math.round((done / total) * 100);

  return (
    <div
      role="progressbar"
      aria-label={label}
      aria-valuenow={percent}
      aria-valuemin={0}
      aria-valuemax={100}
    >
      {percent}%
    </div>
  );
}

// d01_jsx_rendering / ex5 - reference solution.

export function Excerpt({ text, limit }: { text: string; limit: number }) {
  const shown = text.length > limit ? `${text.slice(0, limit).trimEnd()}...` : text;

  return <p>{shown}</p>;
}

// d01_jsx_rendering / ex6 - reference solution.

export function LiteralNotice({ text }: { text: string }) {
  return <p>{text}</p>;
}

// d01_jsx_rendering / ex7 - reference solution.

export function StarRating({ rating, max }: { rating: number; max: number }) {
  const glyphs = "*".repeat(rating) + ".".repeat(max - rating);

  return (
    <span role="img" aria-label={`${rating} out of ${max} stars`}>
      <span aria-hidden="true">{glyphs}</span>
    </span>
  );
}

// d01_jsx_rendering / ex8 - reference solution.

export function SortHeader({
  label,
  direction,
}: {
  label: string;
  direction?: "asc" | "desc";
}) {
  const sort =
    direction === "asc" ? "ascending" : direction === "desc" ? "descending" : undefined;
  const arrow = direction === "asc" ? "^" : direction === "desc" ? "v" : null;

  return (
    <th scope="col" aria-sort={sort}>
      <button type="button">
        {label}
        {arrow === null ? null : <span aria-hidden="true">{arrow}</span>}
      </button>
    </th>
  );
}

