  name,
  salutation = "Hello",
}: {
  name: string;
  salutation?: string;
}) {
  return (
    <p>
      {salutation}, {name}!
    </p>
  );
}

// d02_components_props / ex2 - reference solution.

export function Avatar({
  src,
  name,
  size = 40,
}: {
  src: string;
  name: string;
  size?: number;
}) {
  return <img src={src} alt={name} width={size} height={size} />;
}

// d02_components_props / ex3 - reference solution.

export function LinkButton({
  href,
  label,
  external = false,
}: {
  href: string;
  label: string;
  external?: boolean;
}) {
  return (
    <a href={href} target={external ? "_blank" : undefined} rel={external ? "noreferrer" : undefined}>
      {label}
      {external ? <span> (opens in a new tab)</span> : null}
    </a>
  );
}

// d02_components_props / ex4 - reference solution.

export function Stepper({
  value,
  step = 1,
  min,
  max,
  onChange,
}: {
  value: number;
  step?: number;
  min: number;
  max: number;
  onChange: (next: number) => void;
}) {
  return (
    <>
      <button type="button" disabled={value <= min} onClick={() => onChange(value - step)}>
        Decrease
      </button>
      <output>{value}</output>
      <button type="button" disabled={value >= max} onClick={() => onChange(value + step)}>
        Increase
      </button>
    </>
  );
}

// d02_components_props / ex5 - reference solution.

const LABELS: Record<string, string> = {
  queued: "Queued",
  running: "Running",
  done: "Done",
  failed: "Failed",
};

export function StatusPill({ status }: { status: string }) {
  const label = LABELS[status];
  if (label === undefined) {
    return null;
  }

  return <span role={status === "failed" ? "alert" : "status"}>{label}</span>;
}

// d02_components_props / ex6 - reference solution.

export function PageInfo({
  page,
  pageSize,
  total,
}: {
  page: number;
  pageSize: number;
  total: number;
}) {
  if (total === 0) {
    return <p>No results</p>;
  }

  const first = (page - 1) * pageSize + 1;
  const last = Math.min(page * pageSize, total);

  return (
    <p>
      Showing {first}-{last} of {total}
    </p>
  );
}

// d02_components_props / ex7 - reference solution.
import { useId } from "react";

export function ToggleRow({
  label,
  checked,
  onChange,
  description,
  disabled = false,
}: {
  label: string;
  checked: boolean;
  onChange: (next: boolean) => void;
  description?: string;
  disabled?: boolean;
}) {
  const descriptionId = useId();

  return (
    <div>
      <button
        type="button"
        role="switch"
        aria-checked={checked}
        aria-describedby={description === undefined ? undefined : descriptionId}
        disabled={disabled}
        onClick={() => onChange(!checked)}
      >
        {label}
      </button>
      {description === undefined ? null : <p id={descriptionId}>{description}</p>}
    </div>
  );
}

// d02_components_props / ex8 - reference solution.

export function NoticeBar({
  message,
  footer = "Nothing to do",
  onDismiss,
}: {
  message: string;
  footer?: string | null;
  onDismiss?: () => void;
}) {
  return (
    <div>
      <p>{message}</p>
      {footer === null ? null : <p>{footer}</p>}
      {onDismiss === undefined ? null : (
        <button type="button" onClick={onDismiss}>
          Dismiss
        </button>
      )}
    </div>
  );
}

