// d03_children_composition / ex1 - reference solution.
import type { ReactNode } from "react";

export function Section({ title, children }: { title: string; children: ReactNode }) {
  return (
    <section>
      <h2>{title}</h2>
      {children}
    </section>
  );
}

// d03_children_composition / ex2 - reference solution.
import type { ReactNode } from "react";

export function FieldWrapper({ label, children }: { label: string; children: ReactNode }) {
  return (
    <label>
      <span>{label}</span>
      {children}
    </label>
  );
}

// d03_children_composition / ex3 - reference solution.
import type { ReactNode } from "react";

export function Banner({ tone, children }: { tone: string; children: ReactNode }) {
  return <div role={tone === "urgent" ? "alert" : "status"}>{children}</div>;
}

// d03_children_composition / ex4 - reference solution.
import type { ReactNode } from "react";

export function PageLayout({
  header,
  sidebar,
  children,
}: {
  header: ReactNode;
  sidebar: ReactNode;
  children: ReactNode;
}) {
  return (
    <div>
      <header>{header}</header>
      <aside>{sidebar}</aside>
      <main>{children}</main>
    </div>
  );
}

// d03_children_composition / ex5 - reference solution.
import type { ReactNode } from "react";

export function Button({
  tone = "default",
  children,
  onClick,
}: {
  tone?: string;
  children: ReactNode;
  onClick: () => void;
}) {
  return (
    <button type="button" onClick={onClick}>
      {children}
      {tone === "danger" ? <span> (cannot be undone)</span> : null}
    </button>
  );
}

export function DangerButton({ children, onClick }: { children: ReactNode; onClick: () => void }) {
  return (
    <Button tone="danger" onClick={onClick}>
      {children}
    </Button>
  );
}

// d03_children_composition / ex6 - reference solution.
import { useCallback, useState, type ReactNode } from "react";

export type TogglerState = { on: boolean; toggle: () => void };

export function Toggler({ children }: { children: (state: TogglerState) => ReactNode }) {
  const [on, setOn] = useState(false);
  const toggle = useCallback(() => setOn((current) => !current), []);

  return <>{children({ on, toggle })}</>;
}

// d03_children_composition / ex7 - reference solution.
import { Children, isValidElement, type ReactNode } from "react";

export function Case({ when, children }: { when: string; children: ReactNode }) {
  return <>{children}</>;
}

export function Switcher({
  value,
  fallback,
  children,
}: {
  value: string;
  fallback: ReactNode;
  children: ReactNode;
}) {
  const match = Children.toArray(children).find(
    (child) =>
      isValidElement<{ when: string }>(child) && child.type === Case && child.props.when === value,
  );

  if (isValidElement<{ children?: ReactNode }>(match)) {
    return <>{match.props.children}</>;
  }

  return <>{fallback}</>;
}

// d03_children_composition / ex8 - reference solution.
import {
  Children,
  createContext,
  isValidElement,
  useContext,
  useId,
  type ComponentPropsWithoutRef,
  type ReactNode,
} from "react";

type FormFieldContextValue = { controlId: string; hintId: string | undefined };

const FormFieldContext = createContext<FormFieldContextValue>({
  controlId: "",
  hintId: undefined,
});

function FormFieldRoot({ children }: { children: ReactNode }) {
  const id = useId();
  const hasHint = Children.toArray(children).some(
    (child) => isValidElement(child) && child.type === Hint,
  );

  return (
    <FormFieldContext.Provider
      value={{ controlId: `${id}-control`, hintId: hasHint ? `${id}-hint` : undefined }}
    >
      <div>{children}</div>
    </FormFieldContext.Provider>
  );
}

function Label({ children }: { children: ReactNode }) {
  const { controlId } = useContext(FormFieldContext);
  return <label htmlFor={controlId}>{children}</label>;
}

function Control(props: ComponentPropsWithoutRef<"input">) {
  const { controlId, hintId } = useContext(FormFieldContext);
  return <input id={controlId} aria-describedby={hintId} {...props} />;
}

function Hint({ children }: { children: ReactNode }) {
  const { hintId } = useContext(FormFieldContext);
  return <p id={hintId}>{children}</p>;
}

export const FormField = Object.assign(FormFieldRoot, { Label, Control, Hint });

