// d04_state_basics / ex1 - reference solution.
import { useState } from "react";

export function WaterTracker({ goal }: { goal: number }) {
  const [glasses, setGlasses] = useState(0);

  return (
    <>
      <p role="status">
        {glasses} of {goal} glasses
      </p>
      <button type="button" onClick={() => setGlasses(glasses + 1)} disabled={glasses >= goal}>
        Drink
      </button>
      <button type="button" onClick={() => setGlasses(0)}>
        Reset
      </button>
    </>
  );
}

// d04_state_basics / ex2 - reference solution.
import { useState } from "react";

export function Spoiler({ text }: { text: string }) {
  const [shown, setShown] = useState(false);

  return (
    <>
      <button type="button" onClick={() => setShown(!shown)}>
        {shown ? "Hide spoiler" : "Show spoiler"}
      </button>
      {shown ? <p>{text}</p> : null}
    </>
  );
}

// d04_state_basics / ex3 - reference solution.
import { useState } from "react";

export function DraftBox({ makeInitial }: { makeInitial: () => string }) {
  const [draft, setDraft] = useState(makeInitial);

  return (
    <>
      <p role="status">{draft}</p>
      <button type="button" onClick={() => setDraft((current) => current + "!")}>
        Append
      </button>
    </>
  );
}

// d04_state_basics / ex4 - reference solution.
import { useState } from "react";

export function QueueBoard({ names }: { names: string[] }) {
  const [queue, setQueue] = useState<string[]>([]);
  const next = queue.length > 0 ? queue[0] : "nobody";

  return (
    <>
      <p role="status">
        {queue.length} waiting - Next: {next}
      </p>
      <button
        type="button"
        onClick={() => setQueue((current) => [...current, names[current.length]])}
        disabled={queue.length >= names.length}
      >
        Add
      </button>
      <button
        type="button"
        onClick={() => setQueue((current) => current.slice(1))}
        disabled={queue.length === 0}
      >
        Remove first
      </button>
    </>
  );
}

// d04_state_basics / ex5 - reference solution.

export function SearchSummary({
  items,
  query,
  onRender,
}: {
  items: string[];
  query: string;
  onRender: () => void;
}) {
  onRender();

  const matches = items.filter((item) => item.toLowerCase().includes(query.toLowerCase()));
  const summary =
    query === ""
      ? `Showing all ${items.length} items`
      : `${matches.length} of ${items.length} items match ${query}`;

  return <p role="status">{summary}</p>;
}

// d04_state_basics / ex6 - reference solution.
import { useState } from "react";

const INITIAL = { channels: { email: true, sms: false }, quietHours: false };

export function NotificationSettings() {
  const [settings, setSettings] = useState(INITIAL);

  function toggleChannel(channel: "email" | "sms") {
    setSettings((current) => ({
      ...current,
      channels: { ...current.channels, [channel]: !current.channels[channel] },
    }));
  }

  return (
    <>
      <button
        type="button"
        role="switch"
        aria-checked={settings.channels.email}
        onClick={() => toggleChannel("email")}
      >
        Email
      </button>
      <button
        type="button"
        role="switch"
        aria-checked={settings.channels.sms}
        onClick={() => toggleChannel("sms")}
      >
        SMS
      </button>
      <button
        type="button"
        role="switch"
        aria-checked={settings.quietHours}
        onClick={() => setSettings((current) => ({ ...current, quietHours: !current.quietHours }))}
      >
        Quiet hours
      </button>
      <button type="button" onClick={() => setSettings(INITIAL)}>
        Revert
      </button>
    </>
  );
}

// d04_state_basics / ex7 - reference solution.
import { useRef, useState } from "react";

export function DelayedCounter() {
  const [count, setCount] = useState(0);
  const pending = useRef<ReturnType<typeof setTimeout>[]>([]);

  function later() {
    const id = setTimeout(() => {
      setCount((current) => current + 1);
    }, 1000);
    pending.current.push(id);
  }

  function reset() {
    pending.current.forEach(clearTimeout);
    pending.current = [];
    setCount(0);
  }

  return (
    <>
      <p role="status">Count: {count}</p>
      <button type="button" onClick={later}>
        Later
      </button>
      <button type="button" onClick={reset}>
        Reset
      </button>
    </>
  );
}

// d04_state_basics / ex8 - reference solution.
import { useState } from "react";

export function TitleDraft({ noteId, initialTitle }: { noteId: string; initialTitle: string }) {
  const [title, setTitle] = useState(initialTitle);
  const [shownNoteId, setShownNoteId] = useState(noteId);

  if (noteId !== shownNoteId) {
    setShownNoteId(noteId);
    setTitle(initialTitle);
  }

  return (
    <>
      <label htmlFor="note-title">Title</label>
      <input id="note-title" value={title} onChange={(event) => setTitle(event.target.value)} />
    </>
  );
}

