// d05_events_updates / ex1 - reference solution.

export function DoorBell({ onRing }: { onRing: () => void }) {
  return (
    <button type="button" onClick={() => onRing()}>
      Ring
    </button>
  );
}

// d05_events_updates / ex2 - reference solution.

export function Keypad({ onPress }: { onPress: (key: number | "clear") => void }) {
  return (
    <>
      {[1, 2, 3].map((digit) => (
        <button key={digit} type="button" onClick={() => onPress(digit)}>
          {digit}
        </button>
      ))}
      <button type="button" onClick={() => onPress("clear")}>
        Clear
      </button>
    </>
  );
}

// d05_events_updates / ex3 - reference solution.

export function LinkGuard({ href, onNavigate }: { href: string; onNavigate: (to: string) => void }) {
  return (
    <a
      href={href}
      onClick={(event) => {
        event.preventDefault();
        onNavigate(href);
      }}
    >
      Settings
    </a>
  );
}

// d05_events_updates / ex4 - reference solution.

export function NotificationCard({
  title,
  onOpen,
  onDismiss,
}: {
  title: string;
  onOpen: () => void;
  onDismiss: () => void;
}) {
  return (
    <div role="group" aria-label="Notification" onClick={() => onOpen()}>
      <p>{title}</p>
      <button
        type="button"
        onClick={(event) => {
          event.stopPropagation();
          onDismiss();
        }}
      >
        Dismiss
      </button>
    </div>
  );
}

// d05_events_updates / ex5 - reference solution.
import { useState } from "react";

export function HotkeyBox({ onSubmit }: { onSubmit: (message: string) => void }) {
  const [message, setMessage] = useState("");

  return (
    <>
      <label htmlFor="message">Message</label>
      <textarea
        id="message"
        value={message}
        onChange={(event) => setMessage(event.target.value)}
        onKeyDown={(event) => {
          if (event.key === "Enter" && !event.shiftKey) {
            event.preventDefault();
            onSubmit(message);
            setMessage("");
            return;
          }
          if (event.key === "Escape") {
            setMessage("");
          }
        }}
      />
    </>
  );
}

// d05_events_updates / ex6 - reference solution.
import { useState } from "react";

export function Basket({ onLog }: { onLog: (count: number) => void }) {
  const [count, setCount] = useState(0);

  function addTwo() {
    setCount((current) => current + 1);
    setCount((current) => current + 1);
    onLog(count);
  }

  return (
    <>
      <p role="status">{count} in basket</p>
      <button type="button" onClick={addTwo}>
        Add two
      </button>
    </>
  );
}

// d05_events_updates / ex7 - reference solution.
import type { MouseEvent } from "react";

export function EditorToolbar({ onCommand }: { onCommand: (command: string) => void }) {
  function handleClick(event: MouseEvent<HTMLDivElement>) {
    const button = (event.target as HTMLElement).closest<HTMLButtonElement>("button");
    const command = button?.dataset.command;
    if (command) {
      onCommand(command);
    }
  }

  return (
    <div role="toolbar" aria-label="Formatting" onClick={handleClick}>
      <button type="button" data-command="bold">
        Bold
      </button>
      <button type="button" data-command="italic">
        Italic
      </button>
      <button type="button" data-command="link">
        Link
      </button>
    </div>
  );
}

// d05_events_updates / ex8 - reference solution.
import { useEffect, useRef } from "react";

export function TapTarget({ onSingle, onDouble }: { onSingle: () => void; onDouble: () => void }) {
  const pending = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(
    () => () => {
      if (pending.current !== null) {
        clearTimeout(pending.current);
      }
    },
    [],
  );

  function handleClick() {
    if (pending.current !== null) {
      clearTimeout(pending.current);
      pending.current = null;
      onDouble();
      return;
    }

    pending.current = setTimeout(() => {
      pending.current = null;
      onSingle();
    }, 250);
  }

  return (
    <button type="button" onClick={handleClick}>
      Tap
    </button>
  );
}

