// d06_lists_keys / ex1 - reference solution.

export function RecipeSteps({ steps }: { steps: string[] }) {
  return (
    <ol>
      {steps.map((step) => (
        <li key={step}>{step}</li>
      ))}
    </ol>
  );
}

// d06_lists_keys / ex2 - reference solution.

export function HighScores({ scores }: { scores: { name: string; points: number }[] }) {
  const ranked = [...scores].sort((a, b) => b.points - a.points);

  return (
    <ul>
      {ranked.map((score) => (
        <li key={score.name}>
          {score.name} - {score.points}
        </li>
      ))}
    </ul>
  );
}

// d06_lists_keys / ex3 - reference solution.

export function Mentions({
  messages,
  me,
}: {
  messages: { id: string; text: string }[];
  me: string;
}) {
  const mine = messages.filter((message) => message.text.includes(`@${me}`));

  if (mine.length === 0) {
    return <p>No mentions yet</p>;
  }

  return (
    <ul>
      {mine.map((message) => (
        <li key={message.id}>{message.text}</li>
      ))}
    </ul>
  );
}

// d06_lists_keys / ex4 - reference solution.
import { useState } from "react";

export function SortableRoster({ people }: { people: { id: string; name: string }[] }) {
  const [sorted, setSorted] = useState(false);
  const rows = sorted ? [...people].sort((a, b) => a.name.localeCompare(b.name)) : people;

  return (
    <>
      <button type="button" onClick={() => setSorted(true)}>
        Sort by name
      </button>
      <ul>
        {rows.map((person) => (
          <li key={person.id}>
            <label htmlFor={`note-${person.id}`}>{person.name}</label>
            <input id={`note-${person.id}`} defaultValue="" />
          </li>
        ))}
      </ul>
    </>
  );
}

// d06_lists_keys / ex5 - reference solution.
import { Fragment } from "react";

export function Glossary({
  entries,
}: {
  entries: { id: string; term: string; definition: string }[];
}) {
  return (
    <dl>
      {entries.map((entry) => (
        <Fragment key={entry.id}>
          <dt>{entry.term}</dt>
          <dd>{entry.definition}</dd>
        </Fragment>
      ))}
    </dl>
  );
}

// d06_lists_keys / ex6 - reference solution.

export function AuthorLine({ names }: { names: string[] }) {
  const line =
    names.length === 0
      ? "Unknown author"
      : names.length === 1
        ? names[0]
        : `${names.slice(0, -1).join(", ")} and ${names[names.length - 1]}`;

  return <p>{line}</p>;
}

// d06_lists_keys / ex7 - reference solution.
import { useState } from "react";

type Item = { id: string; text: string };

export function EditableList({ initialItems }: { initialItems: Item[] }) {
  const [items, setItems] = useState(initialItems);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [draft, setDraft] = useState("");

  function save() {
    setItems(items.map((item) => (item.id === editingId ? { ...item, text: draft } : item)));
    setEditingId(null);
  }

  return (
    <ul>
      {items.map((item) =>
        item.id === editingId ? (
          <li key={item.id}>
            <input
              aria-label="Item text"
              value={draft}
              onChange={(event) => setDraft(event.target.value)}
            />
            <button type="button" onClick={save}>
              Save
            </button>
            <button type="button" onClick={() => setEditingId(null)}>
              Cancel
            </button>
          </li>
        ) : (
          <li key={item.id}>
            <span>{item.text}</span>
            <button
              type="button"
              onClick={() => {
                setEditingId(item.id);
                setDraft(item.text);
              }}
            >
              Edit {item.text}
            </button>
          </li>
        ),
      )}
    </ul>
  );
}

// d06_lists_keys / ex8 - reference solution.
import { useState } from "react";

export function SearchableChecklist({ items }: { items: { id: string; label: string }[] }) {
  const [filter, setFilter] = useState("");
  const visible = items.filter((item) =>
    item.label.toLowerCase().includes(filter.toLowerCase()),
  );

  return (
    <>
      <label>
        Filter
        <input value={filter} onChange={(event) => setFilter(event.target.value)} />
      </label>
      <ul>
        {visible.map((item) => (
          <li key={item.id}>
            <label>
              {item.label}
              <input type="checkbox" />
            </label>
          </li>
        ))}
      </ul>
    </>
  );
}

