// d07_conditional_ui / ex1 - reference solution.

export function AuthNav({ user }: { user: { name: string } | null }) {
  if (user === null) {
    return <button type="button">Sign in</button>;
  }

  return (
    <>
      <span>Hi, {user.name}</span>
      <button type="button">Sign out</button>
    </>
  );
}

// d07_conditional_ui / ex2 - reference solution.

export function CartBadge({ count }: { count: number }) {
  if (count === 0) {
    return null;
  }

  return <span role="status">{count}</span>;
}

// d07_conditional_ui / ex3 - reference solution.

export function MaintenanceBanner({ notice }: { notice: string | null }) {
  if (notice === null) {
    return null;
  }

  return <p role="status">{notice}</p>;
}

// d07_conditional_ui / ex4 - reference solution.

type Order =
  | { status: "pending" }
  | { status: "shipped"; carrier: string; trackingUrl: string }
  | { status: "delivered"; deliveredAt: string; deliveredOn: string }
  | { status: "cancelled"; reason: string };

export function OrderStatus({ order }: { order: Order }) {
  switch (order.status) {
    case "pending":
      return <p>Placing order</p>;
    case "shipped":
      return <a href={order.trackingUrl}>Track with {order.carrier}</a>;
    case "delivered":
      return (
        <p>
          Delivered <time dateTime={order.deliveredAt}>{order.deliveredOn}</time>
        </p>
      );
    case "cancelled":
      return <p role="alert">Cancelled: {order.reason}</p>;
  }
}

// d07_conditional_ui / ex5 - reference solution.
import type { ReactNode } from "react";

type User = { name: string; entitlements: string[] };

export function AccessGate({
  user,
  feature,
  children,
}: {
  user: User | null;
  feature: string;
  children: ReactNode;
}) {
  if (user === null) {
    return <p>Sign in to continue</p>;
  }

  if (!user.entitlements.includes(feature)) {
    return <p>Upgrade to Pro</p>;
  }

  return <>{children}</>;
}

// d07_conditional_ui / ex6 - reference solution.

export function SaveButton({ dirty, saving }: { dirty: boolean; saving: boolean }) {
  return (
    <button
      type="button"
      disabled={saving || !dirty}
      aria-busy={saving ? "true" : undefined}
    >
      {saving ? "Saving" : "Save"}
    </button>
  );
}

// d07_conditional_ui / ex7 - reference solution.

export function ReviewQueueTab({ count, snoozed }: { count: number; snoozed: boolean }) {
  const label = snoozed
    ? "Reviews snoozed"
    : count === 0
      ? "No reviews waiting"
      : `${count} review${count === 1 ? "" : "s"} waiting`;

  const badge = snoozed || count === 0 ? null : count > 9 ? "9+" : String(count);

  return (
    <button type="button" aria-label={label}>
      {badge !== null && <span aria-hidden="true">{badge}</span>}
    </button>
  );
}

// d07_conditional_ui / ex8 - reference solution.
import { useState } from "react";

export function ComposeTabs() {
  const [tab, setTab] = useState<"write" | "preview">("write");
  const [draft, setDraft] = useState("");

  return (
    <>
      <button type="button" aria-pressed={tab === "write"} onClick={() => setTab("write")}>
        Write
      </button>
      <button type="button" aria-pressed={tab === "preview"} onClick={() => setTab("preview")}>
        Preview
      </button>
      {tab === "write" ? (
        <>
          <label htmlFor="draft">Draft</label>
          <textarea
            id="draft"
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
          />
        </>
      ) : (
        <section aria-label="Preview">{draft}</section>
      )}
    </>
  );
}

