// d08_forms_controlled / ex1 - reference solution.
import { useState, type ChangeEvent } from "react";

export function NicknameField({ maxLength }: { maxLength: number }) {
  const [nickname, setNickname] = useState("");

  function handleChange(event: ChangeEvent<HTMLInputElement>) {
    const next = event.target.value;
    if (next.length > maxLength || next.includes(" ")) {
      return;
    }
    setNickname(next);
  }

  return (
    <>
      <label htmlFor="nickname">Nickname</label>
      <input id="nickname" value={nickname} onChange={handleChange} />
      <p role="status">
        {nickname.length}/{maxLength}
      </p>
    </>
  );
}

// d08_forms_controlled / ex2 - reference solution.
import { useState } from "react";

const OPTIONS = [
  { value: "standard", label: "Standard", estimate: "Arrives in 5 days" },
  { value: "express", label: "Express", estimate: "Arrives in 2 days" },
  { value: "overnight", label: "Overnight", estimate: "Arrives tomorrow" },
];

export function ShippingChoice({ onChange }: { onChange: (value: string) => void }) {
  const [chosen, setChosen] = useState("");
  const estimate =
    OPTIONS.find((option) => option.value === chosen)?.estimate ?? "Choose a shipping speed";

  return (
    <>
      <div role="radiogroup" aria-label="Shipping">
        {OPTIONS.map((option) => (
          <span key={option.value}>
            <input
              type="radio"
              id={option.value}
              name="shipping"
              value={option.value}
              checked={chosen === option.value}
              onChange={() => {
                setChosen(option.value);
                onChange(option.value);
              }}
            />
            <label htmlFor={option.value}>{option.label}</label>
          </span>
        ))}
      </div>
      <p role="status">{estimate}</p>
    </>
  );
}

// d08_forms_controlled / ex3 - reference solution.
import { useState, type FormEvent } from "react";

export function FeedbackForm({
  onSubmit,
}: {
  onSubmit: (feedback: { category: string; message: string }) => void;
}) {
  const [category, setCategory] = useState("bug");
  const [message, setMessage] = useState("");

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onSubmit({ category, message });
  }

  return (
    <form aria-label="Feedback" onSubmit={handleSubmit}>
      <label htmlFor="category">Category</label>
      <select id="category" value={category} onChange={(event) => setCategory(event.target.value)}>
        <option value="bug">Bug</option>
        <option value="idea">Idea</option>
        <option value="praise">Praise</option>
      </select>

      <label htmlFor="message">Message</label>
      <textarea id="message" value={message} onChange={(event) => setMessage(event.target.value)} />

      <button type="submit">Send feedback</button>
    </form>
  );
}

// d08_forms_controlled / ex4 - reference solution.
import { useState, type ChangeEvent } from "react";

type Address = { street: string; city: string; postcode: string };

const EMPTY: Address = { street: "", city: "", postcode: "" };

export function AddressBlock({ onChange }: { onChange: (address: Address) => void }) {
  const [address, setAddress] = useState<Address>(EMPTY);

  function update(next: Address) {
    setAddress(next);
    onChange(next);
  }

  function handleChange(event: ChangeEvent<HTMLInputElement>) {
    update({ ...address, [event.target.name]: event.target.value });
  }

  return (
    <>
      <label htmlFor="street">Street</label>
      <input id="street" name="street" value={address.street} onChange={handleChange} />

      <label htmlFor="city">City</label>
      <input id="city" name="city" value={address.city} onChange={handleChange} />

      <label htmlFor="postcode">Postcode</label>
      <input id="postcode" name="postcode" value={address.postcode} onChange={handleChange} />

      <button type="button" onClick={() => update(EMPTY)}>
        Clear
      </button>
    </>
  );
}

// d08_forms_controlled / ex5 - reference solution.
import { useState, type ChangeEvent } from "react";

export function QuantityBox({
  onQuantityChange,
}: {
  onQuantityChange: (quantity: number | null) => void;
}) {
  const [text, setText] = useState("");

  function commit(next: string) {
    setText(next);
    onQuantityChange(next === "" ? null : Number(next));
  }

  function handleChange(event: ChangeEvent<HTMLInputElement>) {
    const next = event.target.value;
    if (!/^\d*$/.test(next)) {
      return;
    }
    commit(next);
  }

  function handleBlur() {
    const typed = text === "" ? 1 : Number(text);
    commit(String(Math.min(99, Math.max(1, typed))));
  }

  return (
    <>
      <label htmlFor="quantity">Quantity</label>
      <input
        id="quantity"
        inputMode="numeric"
        value={text}
        onChange={handleChange}
        onBlur={handleBlur}
      />
    </>
  );
}

// d08_forms_controlled / ex6 - reference solution.
import { useState } from "react";

export function CountryCity({ catalogue }: { catalogue: Record<string, string[]> }) {
  const [country, setCountry] = useState("");
  const [city, setCity] = useState("");
  const cities = country === "" ? [] : catalogue[country];

  return (
    <>
      <label htmlFor="country">Country</label>
      <select
        id="country"
        value={country}
        onChange={(event) => {
          setCountry(event.target.value);
          setCity("");
        }}
      >
        <option value="">Choose a country</option>
        {Object.keys(catalogue).map((name) => (
          <option key={name} value={name}>
            {name}
          </option>
        ))}
      </select>

      <label htmlFor="city">City</label>
      <select id="city" value={city} onChange={(event) => setCity(event.target.value)}>
        <option value="">Choose a city</option>
        {cities.map((name) => (
          <option key={name} value={name}>
            {name}
          </option>
        ))}
      </select>

      <button type="button" disabled={country === "" || city === ""}>
        Continue
      </button>
    </>
  );
}

