  const [username, setUsername] = useState("");
  const [touched, setTouched] = useState(false);

  const error = username.trim().length < 3 ? "Username must be at least 3 characters" : "";
  const shown = touched && error !== "";

  return (
    <>
      <label htmlFor="username">Username</label>
      <input
        id="username"
        value={username}
        onChange={(event) => setUsername(event.target.value)}
        onBlur={() => setTouched(true)}
        aria-invalid={shown ? "true" : "false"}
        aria-describedby={shown ? "username-error" : undefined}
      />
      {shown && <p id="username-error">{error}</p>}
    </>
  );
}

// d09_forms_validation / ex3 - reference solution.
import { useState, type FormEvent } from "react";

export function PasswordPair({ onSubmit }: { onSubmit: (password: string) => void }) {
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [attempted, setAttempted] = useState(false);

  const passwordError = password === "" ? "Password is required" : "";
  const confirmError =
    passwordError === "" && confirm !== password ? "Passwords do not match" : "";

  const showPassword = attempted && passwordError !== "";
  const showConfirm = attempted && confirmError !== "";

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setAttempted(true);
    if (passwordError !== "" || confirmError !== "") {
      return;
    }
    onSubmit(password);
  }

  return (
    <form onSubmit={handleSubmit}>
      <label htmlFor="password">Password</label>
      <input
        id="password"
        type="password"
        value={password}
        onChange={(event) => setPassword(event.target.value)}
        aria-invalid={showPassword ? "true" : "false"}
        aria-describedby={showPassword ? "password-error" : undefined}
      />
      {showPassword && <p id="password-error">{passwordError}</p>}

      <label htmlFor="confirm">Confirm password</label>
      <input
        id="confirm"
        type="password"
        value={confirm}
        onChange={(event) => setConfirm(event.target.value)}
        aria-invalid={showConfirm ? "true" : "false"}
        aria-describedby={showConfirm ? "confirm-error" : undefined}
      />
      {showConfirm && <p id="confirm-error">{confirmError}</p>}

      <button type="submit">Set password</button>
    </form>
  );
}

// d09_forms_validation / ex4 - reference solution.
import { useRef, useState, type FormEvent } from "react";

type Fields = { name: string; email: string; guests: string };
type Errors = Partial<Record<keyof Fields, string>>;

const ORDER: (keyof Fields)[] = ["name", "email", "guests"];

export function BookingForm({
  onSubmit,
}: {
  onSubmit: (booking: { name: string; email: string; guests: number }) => void;
}) {
  const [fields, setFields] = useState<Fields>({ name: "", email: "", guests: "" });
  const [errors, setErrors] = useState<Errors>({});

  const nameRef = useRef<HTMLInputElement>(null);
  const emailRef = useRef<HTMLInputElement>(null);
  const guestsRef = useRef<HTMLInputElement>(null);
  const refs = { name: nameRef, email: emailRef, guests: guestsRef };

  function validate(): Errors {
    const found: Errors = {};
    if (fields.name.trim() === "") {
      found.name = "Name is required";
    }
    if (!fields.email.includes("@")) {
      found.email = "Enter a valid email address";
    }
    const guests = Number(fields.guests);
    if (fields.guests === "" || Number.isNaN(guests) || guests < 1 || guests > 8) {
      found.guests = "Guests must be between 1 and 8";
    }
    return found;
  }

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const found = validate();
    setErrors(found);

    const first = ORDER.find((key) => found[key] !== undefined);
    if (first !== undefined) {
      refs[first].current?.focus();
      return;
    }

    onSubmit({
      name: fields.name.trim(),
      email: fields.email.trim(),
      guests: Number(fields.guests),
    });
  }

  function set(key: keyof Fields, value: string) {
    setFields((current) => ({ ...current, [key]: value }));
  }

  const broken = ORDER.filter((key) => errors[key] !== undefined);

  return (
    <form onSubmit={handleSubmit}>
      {broken.length > 0 && (
        <div role="alert">
          <ul>
            {broken.map((key) => (
              <li key={key}>{errors[key]}</li>
            ))}
          </ul>
        </div>
      )}

      <label htmlFor="name">Name</label>
      <input
        id="name"
        ref={nameRef}
        value={fields.name}
        onChange={(event) => set("name", event.target.value)}
        aria-invalid={errors.name === undefined ? "false" : "true"}
      />

      <label htmlFor="email">Email</label>
      <input
        id="email"
        ref={emailRef}
        value={fields.email}
        onChange={(event) => set("email", event.target.value)}
        aria-invalid={errors.email === undefined ? "false" : "true"}
      />

      <label htmlFor="guests">Guests</label>
      <input
        id="guests"
        ref={guestsRef}
        value={fields.guests}
        onChange={(event) => set("guests", event.target.value)}
        aria-invalid={errors.guests === undefined ? "false" : "true"}
      />

      <button type="submit">Book</button>
    </form>
  );
}

// d09_forms_validation / ex5 - reference solution.
import { useState } from "react";

const PATTERN = /^[A-Z]{3}-\d{4}$/;

export function CouponField({ onApply }: { onApply: (code: string) => void }) {
  const [code, setCode] = useState("");
  const [error, setError] = useState("");

  function handleApply() {
    const normalised = code.trim().toUpperCase();
    if (!PATTERN.test(normalised)) {
      setError("Coupon codes look like ABC-1234");
      return;
    }
    setError("");
    onApply(normalised);
  }

  return (
    <>
      <label htmlFor="coupon">Coupon code</label>
      <input
        id="coupon"
        value={code}
        onChange={(event) => setCode(event.target.value)}
        aria-invalid={error === "" ? "false" : "true"}
        aria-describedby={error === "" ? undefined : "coupon-error"}
      />
      {error !== "" && <p id="coupon-error">{error}</p>}
      <button type="button" onClick={handleApply}>
        Apply
      </button>
    </>
  );
}

// d09_forms_validation / ex6 - reference solution.
import { useState } from "react";

export function DateRange({
  onSubmit,
}: {
  onSubmit: (range: { start: string; end: string }) => void;
}) {
  const [start, setStart] = useState("");
  const [end, setEnd] = useState("");
  const [endError, setEndError] = useState("");

  function handleClick() {
    if (end < start) {
      setEndError("End date cannot be before the start date");
      return;
    }
    setEndError("");
    onSubmit({ start, end });
  }

  return (
    <>
      <label htmlFor="start">Start date</label>
      <input
        id="start"
        type="date"
        value={start}
        onChange={(event) => setStart(event.target.value)}
        // No rule blames the start date, but it still answers the question.
        aria-invalid="false"
      />

      <label htmlFor="end">End date</label>
      <input
        id="end"
        type="date"
        value={end}
        onChange={(event) => {
          setEnd(event.target.value);
          setEndError("");
        }}
        aria-invalid={endError === "" ? "false" : "true"}
        aria-describedby={endError === "" ? undefined : "end-error"}
      />
      {endError !== "" && <p id="end-error">{endError}</p>}

      <button type="button" disabled={start === "" || end === ""} onClick={handleClick}>
        Check availability
      </button>
    </>
  );
}

