## Exercise 7 — the rule the server owns

Edit `ex7/solution.tsx`. `HandleField({ checkAvailable })` renders an input
labelled `Handle`, a `role="status"` region and a `Save` button.
`checkAvailable(handle)` returns a promise of a boolean.

- `Save` is disabled until a check has come back saying the handle is free;
- leaving the field runs the check with the trimmed handle;
- while it is in flight the status region reads `Checking`;
- taken (`false`) becomes the field's error, `That handle is taken`;
- free (`true`) makes the status read `Available` and unlocks `Save`;
- editing the field clears the error, the status and the permission to save,
  because they were all about a value that no longer exists.

```
uv run dojo test react d09_forms_validation ex7
```

references.solution.tsx:
// d09_forms_validation / ex7 - reference solution.
import { useState } from "react";

export function HandleField({
  checkAvailable,
}: {
  checkAvailable: (handle: string) => Promise<boolean>;
}) {
  const [handle, setHandle] = useState("");
  const [status, setStatus] = useState("");
  const [error, setError] = useState("");
  const [available, setAvailable] = useState(false);

  async function check() {
    const asked = handle.trim();
    if (asked === "") {
      return;
    }
    setStatus("Checking");
    setError("");
    setAvailable(false);

    const free = await checkAvailable(asked);
    if (free) {
      setStatus("Available");
      setAvailable(true);
    } else {
      setStatus("");
      setError("That handle is taken");
    }
  }

  function handleChange(next: string) {
    setHandle(next);
    // Whatever the last check decided was about a value that no longer exists.
    setStatus("");
    setError("");
    setAvailable(false);
  }

  return (
    <>
      <label htmlFor="handle">Handle</label>
      <input
        id="handle"
        value={handle}
        onChange={(event) => handleChange(event.target.value)}
        onBlur={() => void check()}
        aria-invalid={error === "" ? "false" : "true"}
        aria-describedby={error === "" ? undefined : "handle-error"}
      />
      {error !== "" && <p id="handle-error">{error}</p>}

      <p role="status">{status}</p>

      <button type="button" disabled={!available}>
        Save
      </button>
    </>
  );
}

// d09_forms_validation / ex8 - reference solution.
import { useState, type FormEvent } from "react";

export function ProfileSetup({
  onSubmit,
}: {
  onSubmit: (profile: { teamName: string; website: string }) => Promise<void>;
}) {
  const [teamName, setTeamName] = useState("");
  const [website, setWebsite] = useState("");
  const [attempted, setAttempted] = useState(false);
  const [saving, setSaving] = useState(false);
  const [status, setStatus] = useState("");

  const teamNameError =
    teamName.trim().length < 3 ? "Team name must be at least 3 characters" : "";
  const websiteError = website.trim().startsWith("https://")
    ? ""
    : "Website must start with https://";

  const showTeamName = attempted && teamNameError !== "";
  const showWebsite = attempted && websiteError !== "";

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setAttempted(true);
    if (saving || teamNameError !== "" || websiteError !== "") {
      return;
    }

    setSaving(true);
    setStatus("");
    try {
      await onSubmit({ teamName: teamName.trim(), website: website.trim() });
      setStatus("Saved");
    } finally {
      setSaving(false);
    }
  }

  return (
    <form onSubmit={handleSubmit}>
      <label htmlFor="team-name">Team name</label>
      <input
        id="team-name"
        value={teamName}
        onChange={(event) => setTeamName(event.target.value)}
        aria-invalid={showTeamName ? "true" : "false"}
        aria-describedby={showTeamName ? "team-name-error" : undefined}
      />
      {showTeamName && <p id="team-name-error">{teamNameError}</p>}

      <label htmlFor="website">Website</label>
      <input
        id="website"
        value={website}
        onChange={(event) => setWebsite(event.target.value)}
        aria-invalid={showWebsite ? "true" : "false"}
        aria-describedby={showWebsite ? "website-error" : undefined}
      />
      {showWebsite && <p id="website-error">{websiteError}</p>}

      <p role="status">{status}</p>

      <button type="submit" disabled={saving}>
        {saving ? "Saving" : "Create profile"}
      </button>
    </form>
  );
}

