// d10_effects_basics / ex1 - reference solution.
import { useEffect } from "react";

export function RoomJoiner({
  roomId,
  label,
  join,
}: {
  roomId: string;
  label: string;
  join: (roomId: string) => void;
}) {
  useEffect(() => {
    join(roomId);
  }, [roomId, join]);

  return (
    <>
      <p>In room {roomId}</p>
      <p>{label}</p>
    </>
  );
}

// d10_effects_basics / ex2 - reference solution.
import { useEffect, useRef, useState } from "react";

export function SavedIndicator({
  value,
  save,
}: {
  value: string;
  save: (value: string) => void;
}) {
  const [saved, setSaved] = useState<string | null>(null);
  const firstRender = useRef(true);

  useEffect(() => {
    if (firstRender.current) {
      firstRender.current = false;
      return;
    }
    save(value);
    setSaved(value);
  }, [value, save]);

  return <p role="status">{saved === null ? "Nothing saved yet" : `Saved ${saved}`}</p>;
}

// d10_effects_basics / ex3 - reference solution.

export function LiveTotal({ items, onRender }: { items: number[]; onRender: () => void }) {
  onRender();

  const total = items.reduce((sum, item) => sum + item, 0);

  return <p role="status">Total: {total}</p>;
}

// d10_effects_basics / ex4 - reference solution.
import { useEffect } from "react";

type Filters = { status: string; sort: string };

export function FilterSync({
  filters,
  apply,
}: {
  filters: Filters;
  apply: (filters: Filters) => void;
}) {
  const { status, sort } = filters;

  useEffect(() => {
    apply({ status, sort });
  }, [status, sort, apply]);

  return (
    <p role="status">
      {status} / {sort}
    </p>
  );
}

// d10_effects_basics / ex5 - reference solution.
import { useState } from "react";

export function PurchaseButton({
  cart,
  onPurchase,
}: {
  cart: string;
  onPurchase: (cart: string) => void;
}) {
  const [orders, setOrders] = useState(0);

  function handleClick() {
    onPurchase(cart);
    setOrders((count) => count + 1);
  }

  return (
    <>
      <button type="button" onClick={handleClick}>
        Buy
      </button>
      <p role="status">Orders: {orders}</p>
    </>
  );
}

// d10_effects_basics / ex6 - reference solution.
import { useEffect, useRef, useState } from "react";

export function Loader({ id, load }: { id: string; load: (id: string) => Promise<string> }) {
  const [text, setText] = useState("Loading");
  const latestLoad = useRef(load);

  useEffect(() => {
    latestLoad.current = load;
  });

  useEffect(() => {
    let current = true;
    latestLoad.current(id).then((value) => {
      if (current) {
        setText(value);
      }
    });
    return () => {
      current = false;
    };
  }, [id]);

  return <p role="status">{text}</p>;
}

// d10_effects_basics / ex7 - reference solution.
import { useState } from "react";

type Product = { id: string; sizes: string[] };

export function ProductPicker({
  product,
  onRender,
}: {
  product: Product;
  onRender: (id: string, size: string) => void;
}) {
  const [choice, setChoice] = useState<{ id: string; size: string } | null>(null);
  const size = choice && choice.id === product.id ? choice.size : product.sizes[0];

  onRender(product.id, size);

  return (
    <>
      {product.sizes.map((option) => (
        <button
          key={option}
          type="button"
          onClick={() => setChoice({ id: product.id, size: option })}
        >
          {option}
        </button>
      ))}
      <p role="status">
        {product.id}: {size}
      </p>
    </>
  );
}

// d10_effects_basics / ex8 - reference solution.
import { useEffect } from "react";

type Chart = { setData: (points: number[]) => void; setSize: (size: number) => void };

export function ChartSync({
  points,
  size,
  theme,
  chart,
}: {
  points: number[];
  size: number;
  theme: string;
  chart: Chart;
}) {
  useEffect(() => {
    chart.setData(points);
  }, [points, chart]);

  useEffect(() => {
    chart.setSize(size);
  }, [size, chart]);

  return <p role="status">{theme}</p>;
}

