// d11_effects_cleanup / ex1 - reference solution.
import { useEffect, useState } from "react";

type Subscribe = (onNames: (names: string[]) => void) => () => void;

export function PresenceList({ subscribe }: { subscribe: Subscribe }) {
  const [names, setNames] = useState<string[]>([]);

  useEffect(() => {
    const unsubscribe = subscribe(setNames);
    return unsubscribe;
  }, [subscribe]);

  return (
    <ul>
      {names.map((name) => (
        <li key={name}>{name}</li>
      ))}
    </ul>
  );
}

// d11_effects_cleanup / ex2 - reference solution.
import { useEffect, useState } from "react";

export function IntervalClock({ tick }: { tick: () => void }) {
  const [seconds, setSeconds] = useState(0);

  useEffect(() => {
    const id = setInterval(() => {
      tick();
      setSeconds((count) => count + 1);
    }, 1000);
    return () => clearInterval(id);
  }, [tick]);

  return <p role="status">{seconds} seconds</p>;
}

// d11_effects_cleanup / ex3 - reference solution.
import { useEffect } from "react";

export function ChannelSwitch({
  channel,
  connect,
}: {
  channel: string;
  connect: (channel: string) => () => void;
}) {
  useEffect(() => {
    const disconnect = connect(channel);
    return disconnect;
  }, [channel, connect]);

  return <p role="status">Listening to {channel}</p>;
}

// d11_effects_cleanup / ex4 - reference solution.
import { useEffect, useState } from "react";

export function Countdown({ from, onDone }: { from: number; onDone: () => void }) {
  const [left, setLeft] = useState(from);
  const [running, setRunning] = useState(false);

  useEffect(() => {
    if (!running) {
      return;
    }
    const id = setInterval(() => {
      setLeft((seconds) => (seconds > 0 ? seconds - 1 : 0));
    }, 1000);
    return () => clearInterval(id);
  }, [running]);

  useEffect(() => {
    if (running && left === 0) {
      setRunning(false);
      onDone();
    }
  }, [running, left, onDone]);

  return (
    <>
      <button type="button" onClick={() => setRunning(true)}>
        Start
      </button>
      <button type="button" onClick={() => setRunning(false)}>
        Pause
      </button>
      <p role="status">Time left: {left}</p>
    </>
  );
}

// d11_effects_cleanup / ex5 - reference solution.
import { useEffect, useRef } from "react";

export function ClickOutside({ onOutside }: { onOutside: () => void }) {
  const boxRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    function handleClick(event: MouseEvent) {
      const box = boxRef.current;
      if (box && !box.contains(event.target as Node)) {
        onOutside();
      }
    }

    document.addEventListener("click", handleClick);
    return () => document.removeEventListener("click", handleClick);
  }, [onOutside]);

  return (
    <div ref={boxRef}>
      <button type="button">Inside</button>
    </div>
  );
}

// d11_effects_cleanup / ex6 - reference solution.
import { useEffect, useState } from "react";

export function Autosave({ text, save }: { text: string; save: (text: string) => void }) {
  const [savedText, setSavedText] = useState(text);

  useEffect(() => {
    if (text === savedText) {
      return;
    }
    const id = setTimeout(() => {
      save(text);
      setSavedText(text);
    }, 500);
    return () => clearTimeout(id);
  }, [text, save, savedText]);

  return <p role="status">{text === savedText ? "All changes saved" : "Unsaved changes"}</p>;
}

// d11_effects_cleanup / ex7 - reference solution.
import { useEffect } from "react";

export function SessionKeeper({ connect }: { connect: () => () => void }) {
  useEffect(() => {
    const close = connect();
    return close;
  }, [connect]);

  return <p role="status">Session open</p>;
}

// d11_effects_cleanup / ex8 - reference solution.
import { useEffect, useState } from "react";

type Subscribe = (source: string, onValue: (value: number) => void) => () => void;

export function LiveTicker({
  source,
  paused,
  subscribe,
}: {
  source: string;
  paused: boolean;
  subscribe: Subscribe;
}) {
  const [value, setValue] = useState<number | null>(null);

  useEffect(() => {
    if (paused) {
      return;
    }
    setValue(null);
    return subscribe(source, setValue);
  }, [source, paused, subscribe]);

  return <p role="status">{value === null ? "No data" : `${source}: ${value}`}</p>;
}

