// d12_fetching_states / ex1 - reference solution.
import { useEffect, useState } from "react";

export type Weather = { tempC: number; summary: string };

export function WeatherCard({
  city,
  fetchWeather,
}: {
  city: string;
  fetchWeather: (city: string) => Promise<Weather>;
}) {
  const [weather, setWeather] = useState<Weather | null>(null);

  useEffect(() => {
    setWeather(null);
    fetchWeather(city).then(setWeather);
  }, [city, fetchWeather]);

  if (weather === null) {
    return <p role="status">Loading weather for {city}</p>;
  }

  return (
    <p>
      {weather.tempC}C, {weather.summary}
    </p>
  );
}

// d12_fetching_states / ex2 - reference solution.
import { useEffect, useState } from "react";

export type Invoice = { total: string };

export function InvoiceView({
  invoiceId,
  load,
}: {
  invoiceId: string;
  load: (invoiceId: string) => Promise<Invoice>;
}) {
  const [invoice, setInvoice] = useState<Invoice | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setInvoice(null);
    setError(null);
    load(invoiceId).then(setInvoice, (reason: unknown) => {
      setError(reason instanceof Error ? reason.message : String(reason));
    });
  }, [invoiceId, load]);

  if (error !== null) {
    return <p role="alert">{error}</p>;
  }
  if (invoice === null) {
    return <p role="status">Loading invoice {invoiceId}</p>;
  }
  return <p>Total: {invoice.total}</p>;
}

// d12_fetching_states / ex3 - reference solution.
import { useEffect, useState } from "react";

export function SearchPanel({
  query,
  search,
}: {
  query: string;
  search: (query: string) => Promise<string[]>;
}) {
  const [results, setResults] = useState<string[] | null>(null);

  useEffect(() => {
    setResults(null);
    search(query).then(setResults);
  }, [query, search]);

  if (results === null) {
    return <p role="status">Searching for {query}</p>;
  }
  if (results.length === 0) {
    return <p>No matches for {query}</p>;
  }

  return (
    <ul>
      {results.map((result) => (
        <li key={result}>{result}</li>
      ))}
    </ul>
  );
}

// d12_fetching_states / ex4 - reference solution.
import { useEffect, useState } from "react";

export function StockLevel({
  sku,
  fetchLevel,
}: {
  sku: string;
  fetchLevel: (sku: string) => Promise<number>;
}) {
  const [level, setLevel] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    setLoading(true);
    fetchLevel(sku).then((value) => {
      setLevel(value);
      setLoading(false);
    });
  }, [sku, fetchLevel, attempt]);

  return (
    <>
      {level === null ? <p role="status">Checking stock</p> : <p>In stock: {level}</p>}
      <button type="button" disabled={loading} onClick={() => setAttempt((n) => n + 1)}>
        Refresh
      </button>
    </>
  );
}

