// d12_fetching_states / ex7 - reference solution.
import { useEffect, useState } from "react";

export type Customer = { id: string; name: string };

type Loaded = { name: string; orders: string[] };

export function CustomerOrders({
  customerId,
  fetchCustomer,
  fetchOrders,
}: {
  customerId: string;
  fetchCustomer: (customerId: string) => Promise<Customer>;
  fetchOrders: (customerId: string) => Promise<string[]>;
}) {
  const [loaded, setLoaded] = useState<Loaded | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setLoaded(null);
    setError(null);
    fetchCustomer(customerId)
      .then((customer) =>
        fetchOrders(customer.id).then((orders) => ({ name: customer.name, orders })),
      )
      .then(setLoaded, (reason: unknown) => {
        setError(reason instanceof Error ? reason.message : String(reason));
      });
  }, [customerId, fetchCustomer, fetchOrders]);

  if (error !== null) {
    return <p role="alert">{error}</p>;
  }
  if (loaded === null) {
    return <p role="status">Loading customer</p>;
  }

  return (
    <>
      <h2>{loaded.name}</h2>
      <ul>
        {loaded.orders.map((order) => (
          <li key={order}>{order}</li>
        ))}
      </ul>
    </>
  );
}

// d12_fetching_states / ex8 - reference solution.
import { useEffect, useState } from "react";

export type Page = { items: string[]; hasMore: boolean };

export function ActivityFeed({ fetchPage }: { fetchPage: (page: number) => Promise<Page> }) {
  const [items, setItems] = useState<string[]>([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    setLoading(true);
    setError(null);
    fetchPage(page).then(
      (result) => {
        setItems((current) => [...current, ...result.items]);
        setHasMore(result.hasMore);
        setLoading(false);
      },
      (reason: unknown) => {
        setError(reason instanceof Error ? reason.message : String(reason));
        setLoading(false);
      },
    );
  }, [fetchPage, page, attempt]);

  return (
    <>
      <ul>
        {items.map((item) => (
          <li key={item}>{item}</li>
        ))}
      </ul>
      {error !== null ? (
        <>
          <p role="alert">{error}</p>
          <button type="button" onClick={() => setAttempt((n) => n + 1)}>
            Retry
          </button>
        </>
      ) : hasMore ? (
        <button type="button" disabled={loading} onClick={() => setPage((n) => n + 1)}>
          Load more
        </button>
      ) : null}
    </>
  );
}

