// d13_race_abort / ex1 - reference solution.
import { useEffect, useState } from "react";

export function StationBoard({
  station,
  fetchDepartures,
}: {
  station: string;
  fetchDepartures: (station: string) => Promise<string[]>;
}) {
  const [departures, setDepartures] = useState<string[] | null>(null);

  useEffect(() => {
    // Declared inside the effect body, so every run gets its own flag and the
    // cleanup below flips exactly the one belonging to the request it retires.
    let current = true;

    setDepartures(null);
    fetchDepartures(station).then((next) => {
      if (!current) return;
      setDepartures(next);
    });

    return () => {
      current = false;
    };
  }, [station, fetchDepartures]);

  if (departures === null) {
    return <p role="status">Loading departures for {station}</p>;
  }

  return (
    <ul>
      {departures.map((departure) => (
        <li key={departure}>{departure}</li>
      ))}
    </ul>
  );
}

// d13_race_abort / ex2 - reference solution.
import { useEffect, useState } from "react";

export function ShipmentTracker({
  trackingId,
  fetchStatus,
}: {
  trackingId: string;
  fetchStatus: (trackingId: string) => Promise<string>;
}) {
  const [status, setStatus] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let current = true;
    setStatus(null);
    setError(null);

    fetchStatus(trackingId).then(
      (next) => {
        if (!current) return;
        setStatus(next);
      },
      (reason: unknown) => {
        // Same flag, same reason: a request nobody is waiting for cannot
        // report anything, and that includes reporting that it failed.
        if (!current) return;
        setError(reason instanceof Error ? reason.message : String(reason));
      },
    );

    return () => {
      current = false;
    };
  }, [trackingId, fetchStatus]);

  if (error !== null) {
    return <p role="alert">{error}</p>;
  }
  if (status === null) {
    return <p role="status">Checking {trackingId}</p>;
  }
  return <p>{status}</p>;
}

// d13_race_abort / ex3 - reference solution.
import { useEffect, useState } from "react";

export function DocumentPane({
  docId,
  fetchDoc,
}: {
  docId: string;
  fetchDoc: (docId: string, signal: AbortSignal) => Promise<string>;
}) {
  const [text, setText] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // One controller per run of the effect. Its signal goes out with the
    // request; the cleanup aborts it, which both stops the work and tells the
    // callbacks below that this run has been retired.
    const controller = new AbortController();
    setText(null);
    setError(null);

    fetchDoc(docId, controller.signal).then(
      (next) => {
        if (controller.signal.aborted) return;
        setText(next);
      },
      (reason: unknown) => {
        // An abort we asked for arrives here as a rejection. It is not news.
        if (controller.signal.aborted) return;
        setError(reason instanceof Error ? reason.message : String(reason));
      },
    );

    return () => {
      controller.abort();
    };
  }, [docId, fetchDoc]);

  if (error !== null) {
    return <p role="alert">{error}</p>;
  }
  if (text === null) {
    return <p role="status">Loading document {docId}</p>;
  }
  return <p>{text}</p>;
}

// d13_race_abort / ex4 - reference solution.
import { useEffect, useId, useState } from "react";

export function SymbolSearch({ lookup }: { lookup: (ticker: string) => Promise<string> }) {
  const id = useId();
  const [query, setQuery] = useState("");
  const [result, setResult] = useState<string | null>(null);

  // The handler's only job is to record what the user typed. Asking about it
  // is a synchronisation with an outside system, so it belongs in an effect -
  // and an effect comes with the cleanup the guard needs.
  useEffect(() => {
    setResult(null);
    if (query === "") return;

    let current = true;
    lookup(query).then((name) => {
      if (!current) return;
      setResult(name);
    });

    return () => {
      current = false;
    };
  }, [query, lookup]);

  return (
    <>
      <label htmlFor={id}>Ticker</label>
      <input id={id} value={query} onChange={(event) => setQuery(event.target.value)} />
      {query === "" ? (
        <p role="status">Type a ticker</p>
      ) : result === null ? (
        <p role="status">Searching for {query}</p>
      ) : (
        <p>{result}</p>
      )}
    </>
  );
}

// d13_race_abort / ex5 - reference solution.
import { useCallback, useEffect, useRef, useState } from "react";

export function AccountBalance({
  accountId,
  fetchBalance,
}: {
  accountId: string;
  fetchBalance: (accountId: string) => Promise<number>;
}) {
  const [balance, setBalance] = useState<number | null>(null);
  // A ref, not state: bumping the request number must not render anything, and
  // it has to survive the renders that happen while a request is in flight.
  const latest = useRef(0);

  const request = useCallback(() => {
    latest.current += 1;
    const mine = latest.current;
    fetchBalance(accountId).then((next) => {
      // Not "am I the newest arrival" but "am I the newest question".
      if (mine !== latest.current) return;
      setBalance(next);
    });
  }, [accountId, fetchBalance]);

  useEffect(() => {
    request();
  }, [request]);

  return (
    <>
      {balance === null ? <p role="status">Loading balance</p> : <p>Balance: {balance}</p>}
      <button type="button" onClick={request}>
        Refresh
      </button>
    </>
  );
}

// d13_race_abort / ex6 - reference solution.
import { useEffect, useState } from "react";

export function PollenIndex({
  city,
  fetchIndex,
}: {
  city: string;
  fetchIndex: (city: string) => Promise<string>;
}) {
  const [index, setIndex] = useState<string | null>(null);

  useEffect(() => {
    // A ref is one box shared by every run of this effect. A `let` in the
    // effect body is a new box per run, which is what "this request" means.
    let current = true;
    setIndex(null);

    fetchIndex(city).then((next) => {
      if (!current) return;
      setIndex(next);
    });

    return () => {
      current = false;
    };
  }, [city, fetchIndex]);

  if (index === null) {
    return <p role="status">Checking {city}</p>;
  }
  return (
    <p>
      Pollen in {city}: {index}
    </p>
  );
}

// d13_race_abort / ex7 - reference solution.
import { useEffect, useState } from "react";

export type Trip = { id: string; traveller: string };

type Loaded = { traveller: string; legs: string[] };

export function ItineraryPanel({
  tripId,
  fetchTrip,
  fetchLegs,
}: {
  tripId: string;
  fetchTrip: (tripId: string) => Promise<Trip>;
  fetchLegs: (tripId: string) => Promise<string[]>;
}) {
  const [loaded, setLoaded] = useState<Loaded | null>(null);

  useEffect(() => {
    let current = true;
    setLoaded(null);

    fetchTrip(tripId).then((trip) => {
      // The check goes here as well, not only at the end: this is the point
      // where the component decides to spend a second request.
      if (!current) return;
      return fetchLegs(trip.id).then((legs) => {
        if (!current) return;
        setLoaded({ traveller: trip.traveller, legs });
      });
    });

    return () => {
      current = false;
    };
  }, [tripId, fetchTrip, fetchLegs]);

  if (loaded === null) {
    return <p role="status">Loading itinerary</p>;
  }

  return (
    <>
      <h2>{loaded.traveller}</h2>
      <ul>
        {loaded.legs.map((leg) => (
          <li key={leg}>{leg}</li>
        ))}
      </ul>
    </>
  );
}

// d13_race_abort / ex8 - reference solution.
import { useEffect, useRef, useState } from "react";

const METRICS = ["Traffic", "Signups", "Revenue"];

export function MetricTabs({ fetchMetric }: { fetchMetric: (metric: string) => Promise<string> }) {
  const [selected, setSelected] = useState(METRICS[0]);
  // One slot per metric instead of one slot for "the answer". A late answer
  // then has somewhere true to go, and the screen simply reads the slot the
  // user is looking at.
  const [values, setValues] = useState<Record<string, string>>({});
  const requested = useRef(new Set<string>());

  useEffect(() => {
    if (requested.current.has(selected)) return;
    requested.current.add(selected);

    fetchMetric(selected).then((next) => {
      setValues((previous) => ({ ...previous, [selected]: next }));
    });
  }, [selected, fetchMetric]);

  const shown = values[selected];

  return (
    <>
      {METRICS.map((metric) => (
        <button key={metric} type="button" onClick={() => setSelected(metric)}>
          {metric}
        </button>
      ))}
      {shown === undefined ? <p role="status">Loading {selected}</p> : <p>{shown}</p>}
    </>
  );
}

