// d15_ref_patterns / ex1 - reference solution.
import { useEffect, useRef } from "react";

export function PressureGauge({ label, reading }: { label: string; reading: number }) {
  // Per instance, and it survives renders without causing them. A `let` in the
  // component body would reset on every render; a `let` at module scope would
  // be shared by every gauge on the page.
  const previous = useRef<number | null>(null);

  // Read during render, written after the commit - so the value on screen is
  // always the one from the render before this one.
  const was = previous.current;

  useEffect(() => {
    previous.current = reading;
  });

  return (
    <p role="status">
      {label}: now {reading}, was {was === null ? "nothing yet" : was}
    </p>
  );
}

// d15_ref_patterns / ex2 - reference solution.
import { useEffect, useRef } from "react";

export function ImpressionBeacon({
  slotId,
  report,
}: {
  slotId: string;
  report: (slotId: string) => void;
}) {
  // What has already been reported is not something anybody looks at, so it is
  // not state - and if it were state it would land in the array below and the
  // effect would chase its own tail.
  const seen = useRef(new Set<string>());

  useEffect(() => {
    if (seen.current.has(slotId)) return;
    seen.current.add(slotId);
    report(slotId);
  }, [slotId, report]);

  return <p>Showing {slotId}</p>;
}

// d15_ref_patterns / ex3 - reference solution.
import { useImperativeHandle, useState, type Ref } from "react";

export type ScrubberHandle = {
  play: () => void;
  pause: () => void;
  seek: (seconds: number) => void;
};

export function MediaScrubber({
  label,
  ref,
}: {
  label: string;
  ref?: Ref<ScrubberHandle>;
}) {
  const [playing, setPlaying] = useState(false);
  const [position, setPosition] = useState(0);

  // The parent gets this object and nothing else: three verbs, no DOM node, no
  // way to reach around the component and break it.
  useImperativeHandle(
    ref,
    (): ScrubberHandle => ({
      play: () => setPlaying(true),
      pause: () => setPlaying(false),
      seek: (seconds) => setPosition(seconds),
    }),
    [],
  );

  return (
    <p role="status">
      {label}: {playing ? "playing" : "paused"} at {position}s
    </p>
  );
}

// d15_ref_patterns / ex4 - reference solution.
import { useEffect, useRef, useState } from "react";

export function PingMonitor({
  subscribe,
  onMessage,
}: {
  subscribe: (handler: (message: string) => void) => () => void;
  onMessage: (message: string) => void;
}) {
  const [count, setCount] = useState(0);
  // The newest callback, kept somewhere React does not compare. The
  // subscription reads it at the moment a message arrives rather than closing
  // over the one that existed when it was opened.
  const latest = useRef(onMessage);

  useEffect(() => {
    latest.current = onMessage;
  });

  useEffect(() => {
    const unsubscribe = subscribe((message) => {
      latest.current(message);
      setCount((current) => current + 1);
    });
    return unsubscribe;
  }, [subscribe]);

  return <p role="status">Messages: {count}</p>;
}

// d15_ref_patterns / ex5 - reference solution.
import { useRef, useState } from "react";

export function PayoutRequest({ onSubmit }: { onSubmit: () => Promise<void> }) {
  const [sending, setSending] = useState(false);
  // State is what the user sees; this is what the code checks. It is written
  // synchronously, so the second click of a double-click already sees it.
  const busy = useRef(false);

  function request() {
    if (busy.current) return;
    busy.current = true;
    setSending(true);

    onSubmit().finally(() => {
      busy.current = false;
      setSending(false);
    });
  }

  return (
    <>
      <p role="status">{sending ? "Sending" : "Ready"}</p>
      <button type="button" disabled={sending} onClick={request}>
        Request payout
      </button>
    </>
  );
}

// d15_ref_patterns / ex6 - reference solution.
import { useId, useRef, type Ref } from "react";

export function PassphraseBox({ label, ref }: { label: string; ref?: Ref<HTMLInputElement> }) {
  const id = useId();
  // The component's own handle on the node. It exists whether or not a parent
  // asked for one, which is what makes Clear work in both cases.
  const inner = useRef<HTMLInputElement>(null);

  // A callback ref can feed more than one consumer: ours, and whatever the
  // parent passed - which may be a function ref, an object ref, or nothing.
  function attach(node: HTMLInputElement | null) {
    inner.current = node;
    if (typeof ref === "function") {
      ref(node);
    } else if (ref !== undefined && ref !== null) {
      ref.current = node;
    }
  }

  function clear() {
    if (inner.current === null) return;
    inner.current.value = "";
    inner.current.focus();
  }

  return (
    <p>
      <label htmlFor={id}>{label}</label>
      <input id={id} type="text" ref={attach} />
      <button type="button" onClick={clear}>
        Clear {label}
      </button>
    </p>
  );
}

// d15_ref_patterns / ex7 - reference solution.
import { useEffect, useRef, useState } from "react";

export type Session = { id: string; close: () => void };

export function AnalyticsSession({
  label,
  createSession,
}: {
  label: string;
  createSession: () => Session;
}) {
  const session = useRef<Session | null>(null);
  // The documented way to initialise a ref lazily: check, then fill. Passing
  // createSession() as the argument would call it on every render and discard
  // every result but the first.
  if (session.current === null) {
    session.current = createSession();
  }
  const [events, setEvents] = useState(0);

  useEffect(() => {
    const opened = session.current;
    return () => {
      opened?.close();
    };
  }, []);

  return (
    <>
      <p>{label}</p>
      <p role="status">
        Session {session.current.id}, Events: {events}
      </p>
      <button type="button" onClick={() => setEvents((current) => current + 1)}>
        Bump
      </button>
    </>
  );
}

// d15_ref_patterns / ex8 - reference solution.
import { useId, useImperativeHandle, useState, type Ref } from "react";

export type PadHandle = {
  read: () => string;
  insert: (extra: string) => void;
  clear: () => void;
};

export function ScratchPad({ label, ref }: { label: string; ref?: Ref<PadHandle> }) {
  const id = useId();
  const [text, setText] = useState("");

  // The factory closes over `text`, so the handle has to be rebuilt when the
  // text changes - exactly the rule a dependency array always states. The
  // updaters use the functional form and would be fine on their own; `read`
  // is the one that has no other way of seeing the present.
  useImperativeHandle(
    ref,
    (): PadHandle => ({
      read: () => text,
      insert: (extra) => setText((current) => current + extra),
      clear: () => setText(""),
    }),
    [text],
  );

  return (
    <>
      <label htmlFor={id}>{label}</label>
      <textarea id={id} value={text} onChange={(event) => setText(event.target.value)} />
    </>
  );
}

