// d16_context / ex1 - reference solution.
import { createContext, useContext, type ReactNode } from "react";

// Created once, at module scope. A context created inside a component would be
// a different channel on every render, and no consumer would ever match it.
const UnitsContext = createContext("unset");

export function UnitsProvider({ units, children }: { units: string; children: ReactNode }) {
  return <UnitsContext.Provider value={units}>{children}</UnitsContext.Provider>;
}

export function UnitsLabel() {
  const units = useContext(UnitsContext);
  return <p role="status">Units: {units}</p>;
}

// d16_context / ex2 - reference solution.
import { createContext, useContext, type ReactNode } from "react";

// null is the only honest default: there is no sensible workspace name for a
// component rendered outside every provider.
const WorkspaceContext = createContext<string | null>(null);

export function WorkspaceProvider({ name, children }: { name: string; children: ReactNode }) {
  return <WorkspaceContext.Provider value={name}>{children}</WorkspaceContext.Provider>;
}

export function useWorkspace(): string {
  const name = useContext(WorkspaceContext);
  if (name === null) {
    throw new Error("useWorkspace must be used inside a WorkspaceProvider");
  }
  return name;
}

export function WorkspaceName() {
  return <p role="status">Workspace: {useWorkspace()}</p>;
}

// d16_context / ex3 - reference solution.
import { createContext, useContext, type ReactNode } from "react";

const ZoneContext = createContext("unset");

export function ZoneProvider({ zone, children }: { zone: string; children: ReactNode }) {
  return <ZoneContext.Provider value={zone}>{children}</ZoneContext.Provider>;
}

export function ZoneBadge() {
  // Reads the nearest provider above *this* element in the tree, which is what
  // makes nesting an override rather than an assignment.
  const zone = useContext(ZoneContext);
  return <p role="status">Zone: {zone}</p>;
}

// d16_context / ex4 - reference solution.
import { createContext, useContext, useMemo, useState, type ReactNode } from "react";

type VolumeActions = { louder: () => void; quieter: () => void };

// Two channels, because two different sets of components care about two
// different things. The number changes constantly; the actions never do.
const VolumeValueContext = createContext<number | null>(null);
const VolumeActionsContext = createContext<VolumeActions | null>(null);

function useVolumeValue(): number {
  const value = useContext(VolumeValueContext);
  if (value === null) throw new Error("useVolumeValue must be used inside a VolumeProvider");
  return value;
}

function useVolumeActions(): VolumeActions {
  const value = useContext(VolumeActionsContext);
  if (value === null) throw new Error("useVolumeActions must be used inside a VolumeProvider");
  return value;
}

export function VolumeProvider({ children }: { children: ReactNode }) {
  const [volume, setVolume] = useState(5);

  // The updater form means these never need to close over the volume, so the
  // object can be built once and stay identical for the whole lifetime.
  const actions = useMemo<VolumeActions>(
    () => ({
      louder: () => setVolume((current) => current + 1),
      quieter: () => setVolume((current) => current - 1),
    }),
    [],
  );

  return (
    <VolumeValueContext.Provider value={volume}>
      <VolumeActionsContext.Provider value={actions}>{children}</VolumeActionsContext.Provider>
    </VolumeValueContext.Provider>
  );
}

export function VolumeReadout({ onRender }: { onRender: () => void }) {
  onRender();
  const volume = useVolumeValue();
  return <p role="status">Volume: {volume}</p>;
}

export function VolumeButtons({ onRender }: { onRender: () => void }) {
  onRender();
  const { louder, quieter } = useVolumeActions();
  return (
    <>
      <button type="button" onClick={louder}>
        Louder
      </button>
      <button type="button" onClick={quieter}>
        Quieter
      </button>
    </>
  );
}

// d16_context / ex5 - reference solution.
import { createContext, useContext, useMemo, useState, type ReactNode } from "react";

type Account = { name: string; initials: string };

const AccountContext = createContext<Account | null>(null);

function initialsOf(name: string): string {
  return name
    .split(" ")
    .map((part) => part[0] ?? "")
    .join("");
}

export function AccountProvider({ name, children }: { name: string; children: ReactNode }) {
  const [synced, setSynced] = useState(0);

  // The account only changes when the name does. Without this the provider
  // hands out a different object on every render of its own, and React - which
  // compares context values with Object.is - tells every consumer to redraw.
  const value = useMemo<Account>(() => ({ name, initials: initialsOf(name) }), [name]);

  return (
    <AccountContext.Provider value={value}>
      <p role="status">
        Synced {synced} {synced === 1 ? "time" : "times"}
      </p>
      <button type="button" onClick={() => setSynced((current) => current + 1)}>
        Refresh
      </button>
      {children}
    </AccountContext.Provider>
  );
}

export function AccountChip({ onRender }: { onRender: () => void }) {
  onRender();
  const account = useContext(AccountContext);
  if (account === null) return null;
  return (
    <p>
      {account.initials} - {account.name}
    </p>
  );
}

// d16_context / ex6 - reference solution.
import { createContext, useContext, type ReactNode } from "react";

const LevelContext = createContext(1);

export function SectionProvider({ children }: { children: ReactNode }) {
  // Read the level this section is sitting at, publish one deeper. A provider
  // is allowed to consume the same context it provides - that is how a value
  // accumulates down a tree instead of being replaced.
  const level = useContext(LevelContext);
  return <LevelContext.Provider value={Math.min(level + 1, 6)}>{children}</LevelContext.Provider>;
}

export function SectionHeading({ children }: { children: ReactNode }) {
  const level = useContext(LevelContext);
  const Tag = `h${level}` as "h1" | "h2" | "h3" | "h4" | "h5" | "h6";
  return <Tag>{children}</Tag>;
}

// d16_context / ex7 - reference solution.
import { createContext, useContext, type ReactNode } from "react";

export type SafeContext<T> = {
  Provider: (props: { value: T; children: ReactNode }) => ReactNode;
  useValue: () => T;
};

export function createSafeContext<T>(name: string): SafeContext<T> {
  // Each call makes its own channel. Nothing outside this function can reach
  // it, so the only ways in are the Provider and the hook returned below.
  const Context = createContext<T | null>(null);

  function Provider({ value, children }: { value: T; children: ReactNode }) {
    return <Context.Provider value={value}>{children}</Context.Provider>;
  }

  function useValue(): T {
    const value = useContext(Context);
    if (value === null) {
      // `name` was captured when the context was created, which is why the
      // message can be specific without the caller repeating themselves.
      throw new Error(`This hook must be used inside a ${name}`);
    }
    return value;
  }

  return { Provider, useValue };
}

// d16_context / ex8 - reference solution.
import { createContext, useContext, useMemo, type ReactNode } from "react";

export type Prefs = { locale: string; density: string };

const DEFAULTS: Prefs = { locale: "en", density: "cosy" };

const PrefsContext = createContext<Prefs>(DEFAULTS);

export function PrefsProvider({
  prefs,
  children,
}: {
  prefs: Partial<Prefs>;
  children: ReactNode;
}) {
  // What this provider is replacing. At the top of the tree that is DEFAULTS,
  // because that is what the context was created with; deeper down it is
  // whatever the providers above decided.
  const outer = useContext(PrefsContext);

  const value = useMemo<Prefs>(
    () => ({ ...outer, ...prefs }),
    [outer, prefs.locale, prefs.density],
  );

  return <PrefsContext.Provider value={value}>{children}</PrefsContext.Provider>;
}

export function PrefsReadout() {
  const { locale, density } = useContext(PrefsContext);
  return (
    <p role="status">
      {locale} / {density}
    </p>
  );
}

