// d17_reducers / ex1 - reference solution.

export type WizardState = { step: number; total: number };

export type WizardAction = { type: "next" } | { type: "back" } | { type: "reset" };

/** The next step, clamped to the wizard's ends. */
function moveTo(state: WizardState, step: number): WizardState {
  const wanted = Math.min(Math.max(step, 0), state.total - 1);
  // Nothing to do is a real answer, and saying it by handing back the same
  // object lets React skip the render entirely.
  if (wanted === state.step) return state;
  return { ...state, step: wanted };
}

export function wizardReducer(state: WizardState, action: WizardAction): WizardState {
  switch (action.type) {
    case "next":
      return moveTo(state, state.step + 1);
    case "back":
      return moveTo(state, state.step - 1);
    case "reset":
      return moveTo(state, 0);
  }
}

// d17_reducers / ex2 - reference solution.

export type SeatingState = { chosen: string[]; capacity: number };

export type SeatingAction = { type: "toggled"; seat: string } | { type: "cleared" };

export function seatingReducer(state: SeatingState, action: SeatingAction): SeatingState {
  switch (action.type) {
    case "toggled": {
      if (state.chosen.includes(action.seat)) {
        // Giving a seat up is always allowed, capacity or not.
        return { ...state, chosen: state.chosen.filter((seat) => seat !== action.seat) };
      }
      // The rule the reducer owns: a refusal changes nothing, and the way to
      // say "nothing" is the state itself.
      if (state.chosen.length >= state.capacity) return state;
      return { ...state, chosen: [...state.chosen, action.seat] };
    }
    case "cleared":
      return state.chosen.length === 0 ? state : { ...state, chosen: [] };
  }
}

// d17_reducers / ex3 - reference solution.
import { useReducer } from "react";

// The state is the facts and nothing else. There is no `total` here, because a
// total is not a fact - it is an answer you can work out from the facts.
type PollState = Record<string, number>;

type PollAction = { type: "voted"; option: string } | { type: "reset" };

function pollReducer(state: PollState, action: PollAction): PollState {
  switch (action.type) {
    case "voted":
      return { ...state, [action.option]: (state[action.option] ?? 0) + 1 };
    case "reset": {
      const cleared: PollState = {};
      for (const option of Object.keys(state)) cleared[option] = 0;
      return cleared;
    }
  }
}

export function PollPanel({ options }: { options: string[] }) {
  const [counts, dispatch] = useReducer(pollReducer, options, (list) =>
    Object.fromEntries(list.map((option) => [option, 0])),
  );

  const total = Object.values(counts).reduce((sum, count) => sum + count, 0);

  return (
    <>
      {options.map((option) => (
        <button key={option} type="button" onClick={() => dispatch({ type: "voted", option })}>
          Vote for {option}
        </button>
      ))}
      <button type="button" onClick={() => dispatch({ type: "reset" })}>
        Reset
      </button>
      <ul>
        {options.map((option) => (
          <li key={option}>
            {option}: {counts[option] ?? 0}
          </li>
        ))}
      </ul>
      <p role="status">
        {total} {total === 1 ? "vote" : "votes"}
      </p>
    </>
  );
}

// d17_reducers / ex4 - reference solution.
import { useReducer } from "react";

export type BudgetState = { remaining: number };

type BudgetAction = { type: "spent"; amount: number };

function budgetReducer(state: BudgetState, action: BudgetAction): BudgetState {
  return { remaining: state.remaining - action.amount };
}

export function BudgetPlanner({
  plan,
  label,
  parsePlan,
}: {
  plan: string;
  label: string;
  parsePlan: (plan: string) => BudgetState;
}) {
  // Three arguments, not two: the argument and the function that turns it into
  // the initial state. React calls parsePlan(plan) once, on mount - passing
  // parsePlan(plan) directly would run it on every render instead.
  const [state, dispatch] = useReducer(budgetReducer, plan, parsePlan);

  return (
    <>
      <p>{label}</p>
      <p role="status">Remaining: {state.remaining}</p>
      <button type="button" onClick={() => dispatch({ type: "spent", amount: 10 })}>
        Spend 10
      </button>
    </>
  );
}

// d17_reducers / ex5 - reference solution.

export type ModerationTicket = { id: string; status: "open" | "approved" | "rejected" | "escalated" };

export type ModerationState = { tickets: ModerationTicket[] };

export type ModerationAction =
  | { type: "approved"; id: string }
  | { type: "rejected"; id: string }
  | { type: "escalated"; id: string };

export function moderationReducer(
  state: ModerationState,
  action: ModerationAction,
): ModerationState {
  switch (action.type) {
    case "approved":
    case "rejected":
    case "escalated": {
      // The three decisions differ only in the word, so they share a branch.
      const status = action.type;
      const current = state.tickets.find((ticket) => ticket.id === action.id);
      if (current === undefined || current.status === status) return state;

      return {
        ...state,
        tickets: state.tickets.map((ticket) =>
          // A copy for the one that changed; the same object for every other
          // row, so a memoized list has no reason to redraw them.
          ticket.id === action.id ? { ...ticket, status } : ticket,
        ),
      };
    }
    default: {
      // Unreachable if the union is honest - which is the point. An action
      // that gets here is a bug in the caller, and a silent `return state`
      // hides it behind a button that does nothing.
      const unexpected = action as { type: string };
      throw new Error(`moderationReducer: unknown action type ${unexpected.type}`);
    }
  }
}

