// d17_reducers / ex6 - reference solution.

export type JobState = {
  status: "idle" | "running" | "paused" | "done";
  progress: number;
};

export type JobAction =
  | { type: "started" }
  | { type: "paused" }
  | { type: "resumed" }
  | { type: "progressed"; by: number }
  | { type: "finished" }
  | { type: "reset" };

// Every case asks the same question first: is this action legal from where the
// job is now? An illegal one is not an error, it is simply nothing happening.
export function jobReducer(state: JobState, action: JobAction): JobState {
  switch (action.type) {
    case "started":
      return state.status === "idle" ? { status: "running", progress: 0 } : state;

    case "paused":
      return state.status === "running" ? { ...state, status: "paused" } : state;

    case "resumed":
      return state.status === "paused" ? { ...state, status: "running" } : state;

    case "progressed":
      return state.status === "running"
        ? { ...state, progress: Math.min(state.progress + action.by, 100) }
        : state;

    case "finished":
      return state.status === "running" ? { status: "done", progress: 100 } : state;

    case "reset":
      return state.status === "idle" && state.progress === 0
        ? state
        : { status: "idle", progress: 0 };
  }
}

// d17_reducers / ex7 - reference solution.

export type History<S> = { past: S[]; present: S; future: S[] };

export type HistoryAction = { type: "undo" } | { type: "redo" };

/**
 * Wraps any reducer in past/present/future. The wrapped reducer never learns
 * that it has been wrapped - which is only possible because a reducer is a
 * plain function of two arguments.
 */
export function withHistory<S, A extends { type: string }>(
  reducer: (state: S, action: A) => S,
): (state: History<S>, action: A | HistoryAction) => History<S> {
  return (state, action) => {
    if (action.type === "undo") {
      if (state.past.length === 0) return state;
      return {
        past: state.past.slice(0, -1),
        present: state.past[state.past.length - 1],
        future: [state.present, ...state.future],
      };
    }

    if (action.type === "redo") {
      if (state.future.length === 0) return state;
      const [next, ...rest] = state.future;
      return { past: [...state.past, state.present], present: next, future: rest };
    }

    const present = reducer(state.present, action as A);
    // The inner reducer says "nothing happened" by handing its state back, and
    // nothing that happened is nothing to undo.
    if (present === state.present) return state;

    // Doing something new abandons the branch you had undone your way out of.
    return { past: [...state.past, state.present], present, future: [] };
  };
}

// d17_reducers / ex8 - reference solution.
import { useEffect, useReducer } from "react";

type MonitorState = { alerts: string[]; hidden: number; muted: boolean };

type MonitorAction =
  | { type: "received"; text: string }
  | { type: "muteToggled" }
  | { type: "cleared" };

// One place decides what an arriving alert means, and it is handed the current
// state as an argument rather than closing over it.
function monitorReducer(state: MonitorState, action: MonitorAction): MonitorState {
  switch (action.type) {
    case "received":
      return state.muted
        ? { ...state, hidden: state.hidden + 1 }
        : { ...state, alerts: [...state.alerts, action.text] };
    case "muteToggled":
      return { ...state, muted: !state.muted };
    case "cleared":
      return { ...state, alerts: [], hidden: 0 };
  }
}

export function MonitorPanel({
  subscribe,
}: {
  subscribe: (onAlert: (text: string) => void) => () => void;
}) {
  const [state, dispatch] = useReducer(monitorReducer, {
    alerts: [],
    hidden: 0,
    muted: false,
  });

  // `dispatch` is guaranteed stable by React, so this effect depends only on
  // `subscribe` and never re-runs - one subscription, for the whole life of
  // the component, that nevertheless always acts on the current state.
  useEffect(() => subscribe((text) => dispatch({ type: "received", text })), [subscribe]);

  return (
    <>
      <ul>
        {state.alerts.map((alert, index) => (
          <li key={index}>{alert}</li>
        ))}
      </ul>
      <p role="status">{state.hidden} hidden while muted</p>
      <button type="button" onClick={() => dispatch({ type: "muteToggled" })}>
        {state.muted ? "Unmute" : "Mute"}
      </button>
      <button type="button" onClick={() => dispatch({ type: "cleared" })}>
        Clear
      </button>
    </>
  );
}

