// d18_context_reducer_apps / ex1 - reference solution.
import { createContext, useContext, useReducer, type Dispatch, type ReactNode } from "react";

type Toast = { id: number; message: string };

// The counter is part of the state, because "which numbers have been handed
// out" is a fact about this list that no other field records.
type ToastState = { toasts: Toast[]; nextId: number };

type ToastAction = { type: "added"; message: string } | { type: "dismissed"; id: number };

function toastReducer(state: ToastState, action: ToastAction): ToastState {
  switch (action.type) {
    case "added":
      return {
        toasts: [...state.toasts, { id: state.nextId, message: action.message }],
        nextId: state.nextId + 1,
      };
    case "dismissed":
      return { ...state, toasts: state.toasts.filter((toast) => toast.id !== action.id) };
  }
}

const ToastContext = createContext<{
  toasts: Toast[];
  dispatch: Dispatch<ToastAction>;
} | null>(null);

function useToasts() {
  const value = useContext(ToastContext);
  if (value === null) throw new Error("useToasts must be used inside a ToastProvider");
  return value;
}

export function ToastProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(toastReducer, { toasts: [], nextId: 1 });
  return (
    <ToastContext.Provider value={{ toasts: state.toasts, dispatch }}>
      {children}
    </ToastContext.Provider>
  );
}

export function ToastTrigger({ message }: { message: string }) {
  const { dispatch } = useToasts();
  return (
    <button type="button" onClick={() => dispatch({ type: "added", message })}>
      Notify {message}
    </button>
  );
}

export function ToastList() {
  const { toasts, dispatch } = useToasts();
  return (
    <ul>
      {toasts.map((toast) => (
        <li key={toast.id}>
          <span>{toast.message}</span>
          <button type="button" onClick={() => dispatch({ type: "dismissed", id: toast.id })}>
            Dismiss {toast.message}
          </button>
        </li>
      ))}
    </ul>
  );
}

// d18_context_reducer_apps / ex2 - reference solution.
import { createContext, useContext, useReducer, type Dispatch, type ReactNode } from "react";

type WishlistState = { items: string[] };

type WishlistAction = { type: "toggled"; item: string };

function wishlistReducer(state: WishlistState, action: WishlistAction): WishlistState {
  return state.items.includes(action.item)
    ? { items: state.items.filter((item) => item !== action.item) }
    : { items: [...state.items, action.item] };
}

const WishlistContext = createContext<{
  items: string[];
  dispatch: Dispatch<WishlistAction>;
} | null>(null);

function useWishlist() {
  const value = useContext(WishlistContext);
  if (value === null) throw new Error("useWishlist must be used inside a WishlistProvider");
  return value;
}

export function WishlistProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(wishlistReducer, { items: [] });
  return (
    <WishlistContext.Provider value={{ items: state.items, dispatch }}>
      {children}
    </WishlistContext.Provider>
  );
}

export function WishlistToggle({ item }: { item: string }) {
  const { items, dispatch } = useWishlist();
  // Derived, not stored. There is exactly one answer to "is the kettle saved",
  // and it lives in the provider - so every toggle for the kettle reads it.
  const saved = items.includes(item);

  return (
    <button type="button" onClick={() => dispatch({ type: "toggled", item })}>
      {saved ? "Saved" : "Save"} {item}
    </button>
  );
}

export function WishlistCount() {
  const { items } = useWishlist();
  return <p role="status">{items.length} saved</p>;
}

// d18_context_reducer_apps / ex3 - reference solution.
import {
  createContext,
  useContext,
  useId,
  useReducer,
  type Dispatch,
  type ReactNode,
} from "react";

type FlowState = { step: number; email: string };

type FlowAction = { type: "emailChanged"; email: string } | { type: "next" } | { type: "back" };

/** The one place that knows when a step is finished. */
function canLeave(state: FlowState): boolean {
  if (state.step === 0) return state.email.trim() !== "";
  return state.step < 2;
}

function flowReducer(state: FlowState, action: FlowAction): FlowState {
  switch (action.type) {
    case "emailChanged":
      return { ...state, email: action.email };
    case "next":
      // The reducer enforces the rule as well as the button showing it: a
      // disabled button is a courtesy, not a guarantee.
      return canLeave(state) ? { ...state, step: state.step + 1 } : state;
    case "back":
      return state.step <= 0 ? state : { ...state, step: state.step - 1 };
  }
}

const FlowContext = createContext<{
  state: FlowState;
  canNext: boolean;
  canBack: boolean;
  dispatch: Dispatch<FlowAction>;
} | null>(null);

function useFlow() {
  const value = useContext(FlowContext);
  if (value === null) throw new Error("useFlow must be used inside a FlowProvider");
  return value;
}

export function FlowProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(flowReducer, { step: 0, email: "" });

  // Derived here, so a button in one branch of the tree can depend on a field
  // in another without either of them knowing the other exists.
  const canNext = canLeave(state);
  const canBack = state.step > 0;

  return (
    <FlowContext.Provider value={{ state, canNext, canBack, dispatch }}>
      {children}
    </FlowContext.Provider>
  );
}

export function FlowSteps() {
  const id = useId();
  const { state, dispatch } = useFlow();

  if (state.step === 0) {
    return (
      <>
        <label htmlFor={id}>Email</label>
        <input
          id={id}
          value={state.email}
          onChange={(event) => dispatch({ type: "emailChanged", email: event.target.value })}
        />
      </>
    );
  }
  if (state.step === 1) {
    return <p role="status">Confirm {state.email}</p>;
  }
  return <p role="status">Done</p>;
}

export function FlowNav() {
  const { canNext, canBack, dispatch } = useFlow();
  return (
    <>
      <button type="button" disabled={!canBack} onClick={() => dispatch({ type: "back" })}>
        Back
      </button>
      <button type="button" disabled={!canNext} onClick={() => dispatch({ type: "next" })}>
        Next
      </button>
    </>
  );
}

