// d19_custom_hooks_1 / ex1 - reference solution.
import { useCallback, useState } from "react";

export function useCarousel(count: number) {
  const [index, setIndex] = useState(0);

  // The updater form means neither function has to read `index`, so the only
  // thing they depend on is `count` - and `prev` not even that.
  const next = useCallback(() => {
    setIndex((current) => Math.min(current + 1, count - 1));
  }, [count]);

  const prev = useCallback(() => {
    setIndex((current) => Math.max(current - 1, 0));
  }, []);

  // Derived, not stored: two booleans that are always exactly what the index
  // says they are.
  return { index, next, prev, atStart: index === 0, atEnd: index === count - 1 };
}

// d19_custom_hooks_1 / ex2 - reference solution.
import { useCallback, useState, type ChangeEvent } from "react";

export function useTextField(initial: string) {
  const [value, setValue] = useState(initial);

  const onChange = useCallback((event: ChangeEvent<HTMLInputElement>) => {
    setValue(event.target.value);
  }, []);

  const reset = useCallback(() => {
    setValue(initial);
  }, [initial]);

  // "Has this been edited" is a question about the value, not a separate fact
  // to be maintained - so it cannot drift out of step with the value.
  const dirty = value !== initial;

  return { value, onChange, dirty, reset };
}

// d19_custom_hooks_1 / ex3 - reference solution.
import { useCallback, useState } from "react";

export function useTally() {
  // The hook has no storage of its own. This line is a recipe: every component
  // that runs it gets its own useState slot, with its own value.
  const [count, setCount] = useState(0);

  const add = useCallback(() => {
    setCount((current) => current + 1);
  }, []);

  return { count, add };
}

// d19_custom_hooks_1 / ex4 - reference solution.
import { useState } from "react";

export type PriceRow = { id: string; label: string };

// One row, one component, one useState - called unconditionally, exactly once
// per render of this component, which is the whole of the rule.
function Row({ label }: { label: string }) {
  const [marked, setMarked] = useState(false);
  return (
    <li>
      <span>
        {label}: {marked ? "marked" : "unmarked"}
      </span>
      <button type="button" onClick={() => setMarked(true)}>
        Mark {label}
      </button>
    </li>
  );
}

export function PriceRows({ rows }: { rows: PriceRow[] }) {
  return (
    <ul>
      {rows.map((row) => (
        // The key is what tells React this is the same row as last time, so
        // the state stays with it when the list around it changes.
        <Row key={row.id} label={row.label} />
      ))}
    </ul>
  );
}

// d19_custom_hooks_1 / ex5 - reference solution.
import { useCallback, useEffect, useState } from "react";

export function useCountdown(from: number) {
  const [remaining, setRemaining] = useState(from);
  const [running, setRunning] = useState(false);

  useEffect(() => {
    // Two reasons not to be ticking: nobody started it, and there is nothing
    // left to count. Listing `remaining` in the array is what makes the second
    // one take effect the moment it happens.
    if (!running || remaining === 0) return;

    const id = setInterval(() => {
      setRemaining((current) => Math.max(current - 1, 0));
    }, 1000);

    // The half of the effect that pausing and unmounting both depend on.
    return () => clearInterval(id);
  }, [running, remaining]);

  const start = useCallback(() => setRunning(true), []);
  const pause = useCallback(() => setRunning(false), []);
  const reset = useCallback(() => {
    setRunning(false);
    setRemaining(from);
  }, [from]);

  return { remaining, running, start, pause, reset };
}

// d19_custom_hooks_1 / ex6 - reference solution.
import { useMemo } from "react";

export function useFilteredList(items: string[], query: string, onFilter: () => void) {
  // The answer depends on the list and the question and nothing else, so those
  // are the dependencies. Every other render - a click somewhere, a parent
  // redrawing - gets the answer React already has.
  const matches = useMemo(() => {
    onFilter();
    const needle = query.toLowerCase();
    return items.filter((item) => item.toLowerCase().includes(needle));
  }, [items, query, onFilter]);

  return { matches, count: matches.length };
}

// d19_custom_hooks_1 / ex7 - reference solution.
import { useCallback, useMemo, useState } from "react";

export function useCollection(initial: string[]) {
  const [items, setItems] = useState(initial);

  // Every one of these uses the updater form, so none of them closes over
  // `items` and none of them has a dependency.
  const add = useCallback((item: string) => {
    setItems((current) => (current.includes(item) ? current : [...current, item]));
  }, []);

  const remove = useCallback((item: string) => {
    // Returning the state unchanged is how a setter says "nothing happened",
    // and React skips the render for it.
    setItems((current) => (current.includes(item) ? current.filter((e) => e !== item) : current));
  }, []);

  const clear = useCallback(() => {
    setItems((current) => (current.length === 0 ? current : []));
  }, []);

  // The wrapper is memoized too, or the object would be new every render even
  // though everything inside it is stable.
  return useMemo(() => ({ items, add, remove, clear }), [items, add, remove, clear]);
}

// d19_custom_hooks_1 / ex8 - reference solution.
import { useCallback, useMemo, useRef, useState } from "react";

export type FormValues = Record<string, string>;

export type FormErrors = Record<string, string>;

export function useForm(initial: FormValues, validate: (values: FormValues) => FormErrors) {
  const [values, setValues] = useState(initial);
  // The form it started as, captured once. The caller may well hand us a fresh
  // object literal on every render, and reset must not follow that around.
  const original = useRef(initial);

  // Errors are a question about the values, so they are computed from them -
  // never stored, never cleared by hand, never out of date. useMemo is what
  // stops that computation running on renders that changed nothing.
  const errors = useMemo(() => validate(values), [values, validate]);

  const setField = useCallback((name: string, value: string) => {
    setValues((current) => ({ ...current, [name]: value }));
  }, []);

  const reset = useCallback(() => {
    setValues(original.current);
  }, []);

  return {
    values,
    errors,
    isValid: Object.keys(errors).length === 0,
    setField,
    reset,
  };
}

