// d20_custom_hooks_2 / ex1 - reference solution.
import { useEffect, useRef } from "react";

export function useKeyPress(key: string, handler: () => void) {
  // The newest handler, kept somewhere React does not compare. The listener
  // reads it at the moment the key is pressed rather than closing over the one
  // that existed when it was registered.
  const latest = useRef(handler);

  useEffect(() => {
    latest.current = handler;
  });

  useEffect(() => {
    function onKeyDown(event: KeyboardEvent) {
      if (event.key === key) latest.current();
    }

    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
    // Only the key. Putting `handler` here would tear the listener down and
    // put it back on every render of every component using this hook.
  }, [key]);
}

// d20_custom_hooks_2 / ex2 - reference solution.
import { useEffect, useState } from "react";

export function useSubscription<T>(
  subscribe: (onValue: (value: T) => void) => () => void,
  initial: T,
): T {
  const [value, setValue] = useState(initial);

  useEffect(() => {
    // `subscribe` hands back the way to close what it opened, and that is
    // exactly the shape an effect's cleanup wants - so returning it directly
    // is the whole implementation.
    return subscribe(setValue);
  }, [subscribe]);

  return value;
}

// d20_custom_hooks_2 / ex3 - reference solution.
import { useCallback, useState } from "react";

export function usePaged<T>(items: T[], pageSize: number) {
  // What the reader asked for, which is not always a page that exists.
  const [wanted, setWanted] = useState(1);

  const totalPages = Math.max(1, Math.ceil(items.length / pageSize));

  // What they get. Clamping during render means the shown page is correct in
  // the very first render after the list shrinks - an effect that corrected it
  // afterwards would commit one frame of an empty page first.
  const page = Math.min(wanted, totalPages);

  const pageItems = items.slice((page - 1) * pageSize, page * pageSize);

  // Both moves start from the page that is *shown*, not from the one that was
  // asked for - otherwise walking back from a clamped page spends a step
  // undoing a move the reader never saw happen.
  const next = useCallback(() => {
    setWanted((current) => Math.min(Math.min(current, totalPages) + 1, totalPages));
  }, [totalPages]);

  const prev = useCallback(() => {
    setWanted((current) => Math.max(Math.min(current, totalPages) - 1, 1));
  }, [totalPages]);

  return {
    page,
    pageItems,
    totalPages,
    hasNext: page < totalPages,
    hasPrev: page > 1,
    next,
    prev,
  };
}

// d20_custom_hooks_2 / ex4 - reference solution.
import { useCallback, useEffect, useRef } from "react";

export function useDebouncedCallback<A extends unknown[]>(
  fn: (...args: A) => void,
  delay: number,
) {
  // The newest function, so the returned one never has to change identity to
  // stay up to date.
  const latest = useRef(fn);
  useEffect(() => {
    latest.current = fn;
  });

  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Anything still pending when the component goes has nobody left to talk to.
  useEffect(
    () => () => {
      if (timer.current !== null) clearTimeout(timer.current);
    },
    [],
  );

  return useCallback(
    (...args: A) => {
      // Cancelling what was already scheduled is the entire difference between
      // a debounce and a delay.
      if (timer.current !== null) clearTimeout(timer.current);
      timer.current = setTimeout(() => {
        timer.current = null;
        latest.current(...args);
      }, delay);
    },
    [delay],
  );
}

// d20_custom_hooks_2 / ex5 - reference solution.
import { useCallback, useState } from "react";

export type KeyValueStore = {
  getItem: (key: string) => string | null;
  setItem: (key: string, value: string) => void;
};

export function useStorageState(
  key: string,
  initial: string,
  storage: KeyValueStore,
): [string, (next: string) => void] {
  function read(which: string): string {
    const raw = storage.getItem(which);
    return raw === null ? initial : (JSON.parse(raw) as string);
  }

  // The value *and* the key it belongs to. Keeping them together is what makes
  // "this value is out of date" a question you can actually ask.
  const [entry, setEntry] = useState(() => ({ key, value: read(key) }));

  let current = entry;
  if (entry.key !== key) {
    // Adjusting state during render: React throws this render away and runs it
    // again immediately, so nothing is ever committed showing the old key's
    // value under the new key.
    current = { key, value: read(key) };
    setEntry(current);
  }

  const set = useCallback(
    (next: string) => {
      setEntry({ key, value: next });
      storage.setItem(key, JSON.stringify(next));
    },
    [key, storage],
  );

  return [current.value, set];
}

// d20_custom_hooks_2 / ex6 - reference solution.
import { useEffect, useRef, useState } from "react";

export function useIntervalPoll<T>(load: () => Promise<T>, everyMs: number) {
  const [data, setData] = useState<T | null>(null);

  // The newest loader, so a caller writing `load` inline does not restart the
  // polling on every render.
  const latest = useRef(load);
  useEffect(() => {
    latest.current = load;
  });

  // Not state: nothing on screen depends on it, and changing it must not
  // render. It also has to be readable the instant a tick happens.
  const inFlight = useRef(false);

  useEffect(() => {
    let alive = true;

    function poll() {
      if (inFlight.current) return;
      inFlight.current = true;
      latest.current().then(
        (next) => {
          inFlight.current = false;
          if (alive) setData(next);
        },
        () => {
          inFlight.current = false;
        },
      );
    }

    poll();
    const id = setInterval(poll, everyMs);

    return () => {
      alive = false;
      clearInterval(id);
    };
  }, [everyMs]);

  return { data };
}

// d20_custom_hooks_2 / ex7 - reference solution.
import { useCallback, useEffect, useReducer, useRef } from "react";

export function useLoggedReducer<S, A>(
  reducer: (state: S, action: A) => S,
  initial: S,
  log: (action: A, next: S) => void,
): [S, (action: A) => void] {
  const [state, rawDispatch] = useReducer(reducer, initial);

  // The state as it is *now*, written synchronously when an action is
  // dispatched rather than after the render that shows it.
  const currentState = useRef(initial);
  const reducerRef = useRef(reducer);
  const logRef = useRef(log);

  useEffect(() => {
    reducerRef.current = reducer;
    logRef.current = log;
  });

  const dispatch = useCallback((action: A) => {
    // A reducer is pure, so calling it here to find out what happens next
    // costs nothing and changes nothing.
    const next = reducerRef.current(currentState.current, action);
    currentState.current = next;
    logRef.current(action, next);
    rawDispatch(action);
    // Everything that can change lives in a ref, so this dispatch is as stable
    // as the one React gave us - which is the promise the wrapper has to keep.
  }, []);

  return [state, dispatch];
}

// d20_custom_hooks_2 / ex8 - reference solution.
import { useCallback, useEffect, useRef, useState } from "react";

export function useControllableState<T>(options: {
  value?: T;
  defaultValue: T;
  onChange?: (next: T) => void;
}): [T, (next: T) => void] {
  const { value, defaultValue, onChange } = options;

  // Decided once, on the first render, and never revisited: a component that
  // changes from controlled to uncontrolled halfway through its life is a
  // component whose value appears to jump for no reason.
  const controlled = useRef(value !== undefined).current;

  // Kept whether or not it is used, because the number of hooks a component
  // calls may not depend on a prop.
  const [internal, setInternal] = useState(defaultValue);

  const latestOnChange = useRef(onChange);
  useEffect(() => {
    latestOnChange.current = onChange;
  });

  const set = useCallback(
    (next: T) => {
      // When the parent is in charge, asking is all we may do. Keeping a copy
      // as well is what makes a "controlled" component disagree with the parent
      // that is controlling it.
      if (!controlled) setInternal(next);
      latestOnChange.current?.(next);
    },
    [controlled],
  );

  return [controlled ? (value as T) : internal, set];
}

