  onRender,
}: {
  name: string;
  onToggle: () => void;
  onRender: () => void;
}) {
  onRender();
  return (
    <button type="button" onClick={onToggle}>
      Toggle {name}
    </button>
  );
});

export function ColumnBoard({ onFilterRender }: { onFilterRender: () => void }) {
  const id = useId();
  const [board, setBoard] = useState("");
  const [toggles, setToggles] = useState(0);

  // The updater form means this never has to read `toggles`, so its dependency
  // list is empty and the function is the same object for ever.
  const toggleStatus = useCallback(() => {
    setToggles((current) => current + 1);
  }, []);

  return (
    <>
      <label htmlFor={id}>Board name</label>
      <input id={id} value={board} onChange={(event) => setBoard(event.target.value)} />
      <p>Board: {board}</p>
      <p role="status">
        Status toggled {toggles} {toggles === 1 ? "time" : "times"}
      </p>
      <ColumnFilter name="Status" onToggle={toggleStatus} onRender={onFilterRender} />
    </>
  );
}

// d21_memoization / ex3 - reference solution.
import { useMemo } from "react";

export function SlugPreview({ title, onCompute }: { title: string; onCompute: () => void }) {
  // The array is a claim about what the value is made of, not a performance
  // knob. Everything read inside the factory belongs in it - here, the title
  // and the callback.
  const slug = useMemo(() => {
    onCompute();
    return title
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "");
  }, [title, onCompute]);

  return <p role="status">{slug}</p>;
}

// d21_memoization / ex4 - reference solution.
import { memo, useId, useMemo, useState } from "react";

const VisibleTags = memo(function VisibleTags({
  tags,
  onRender,
}: {
  tags: string[];
  onRender: () => void;
}) {
  onRender();
  return (
    <ul>
      {tags.map((tag) => (
        <li key={tag}>{tag}</li>
      ))}
    </ul>
  );
});

export function TagPanel({ tags, onTagsRender }: { tags: string[]; onTagsRender: () => void }) {
  const id = useId();
  const [search, setSearch] = useState("");
  const [ticks, setTicks] = useState(0);

  // Not about speed - filtering four strings costs nothing. This is useMemo's
  // other job: `filter` returns a new array every time it runs, and a new
  // array is a changed prop however identical its contents.
  const visible = useMemo(() => tags.filter((tag) => tag.includes(search)), [tags, search]);

  return (
    <>
      <label htmlFor={id}>Search</label>
      <input id={id} value={search} onChange={(event) => setSearch(event.target.value)} />
      <p role="status">Ticks: {ticks}</p>
      <button type="button" onClick={() => setTicks((current) => current + 1)}>
        Tick
      </button>
      <VisibleTags tags={visible} onRender={onTagsRender} />
    </>
  );
}

// d21_memoization / ex5 - reference solution.
import { memo, useCallback, useState } from "react";

const ZoomControls = memo(function ZoomControls({
  onZoomIn,
  onReset,
  onRender,
}: {
  onZoomIn: () => void;
  onReset: () => void;
  onRender: () => void;
}) {
  onRender();
  return (
    <>
      <button type="button" onClick={onZoomIn}>
        Zoom in
      </button>
      <button type="button" onClick={onReset}>
        Reset zoom
      </button>
    </>
  );
});

export function ZoomPanel({ onControlsRender }: { onControlsRender: () => void }) {
  const [zoom, setZoom] = useState(1);

  // With the updater form the callback never reads `zoom`, so `zoom` is not a
  // dependency - and the function stops being rebuilt by the very thing it
  // exists to change.
  const zoomIn = useCallback(() => setZoom((current) => current + 1), []);
  const reset = useCallback(() => setZoom(1), []);

  return (
    <>
      <p role="status">Zoom: {zoom}</p>
      <ZoomControls onZoomIn={zoomIn} onReset={reset} onRender={onControlsRender} />
    </>
  );
}

// d21_memoization / ex6 - reference solution.
import { memo, useMemo, useState, type ReactNode } from "react";

const Frame = memo(function Frame({
  title,
  children,
  onRender,
}: {
  title: string;
  children: ReactNode;
  onRender: () => void;
}) {
  onRender();
  return (
    <section>
      <h2>{title}</h2>
      {children}
    </section>
  );
});

function Body({ onRender }: { onRender: () => void }) {
  onRender();
  return <p>Nothing to report</p>;
}

export function FrameBoard({
  onFrameRender,
  onBodyRender,
}: {
  onFrameRender: () => void;
  onBodyRender: () => void;
}) {
  const [ticks, setTicks] = useState(0);

  // JSX is an object, and `<Body />` written inline builds a new one on every
  // render - which arrives at Frame as a changed `children` prop. Memoizing
  // the element is what makes the memo on Frame mean anything.
  const body = useMemo(() => <Body onRender={onBodyRender} />, [onBodyRender]);

  return (
    <>
      <p role="status">Ticks: {ticks}</p>
      <button type="button" onClick={() => setTicks((current) => current + 1)}>
        Tick
      </button>
      <Frame title="Summary" onRender={onFrameRender}>
        {body}
      </Frame>
    </>
  );
}

// d21_memoization / ex7 - reference solution.
import { memo, useCallback, useState } from "react";

export type ChecklistItem = { id: string; label: string };

const ChecklistRow = memo(function ChecklistRow({
  item,
  done,
  onToggle,
  onRender,
}: {
  item: ChecklistItem;
  done: boolean;
  onToggle: (id: string) => void;
  onRender: (id: string) => void;
}) {
  onRender(item.id);
  return (
    <li>
      <span>
        {item.label}: {done ? "done" : "to do"}
      </span>
      {/* The row knows which row it is, so it can say so when it calls back.
          That is what lets every row share one handler. */}
      <button type="button" onClick={() => onToggle(item.id)}>
        Toggle {item.label}
      </button>
    </li>
  );
});

export function ChecklistRows({
  items,
  onRowRender,
}: {
  items: ChecklistItem[];
  onRowRender: (id: string) => void;
}) {
  const [done, setDone] = useState<Record<string, boolean>>({});

  // One function for the whole list, built once. An arrow inside the map would
  // be a new function per row per render, and every memoized row would then be
  // a comparison that can never succeed.
  const toggle = useCallback((id: string) => {
    setDone((current) => ({ ...current, [id]: !current[id] }));
  }, []);

  return (
    <ul>
      {items.map((item) => (
        <ChecklistRow
          key={item.id}
          item={item}
          done={done[item.id] ?? false}
          onToggle={toggle}
          onRender={onRowRender}
        />
      ))}
    </ul>
  );
}

// d21_memoization / ex8 - reference solution.
import { memo, useCallback, useMemo, useState } from "react";

const Legend = memo(function Legend({
  series,
  onSelect,
  onRender,
}: {
  series: string[];
  onSelect: (label: string) => void;
  onRender: () => void;
}) {
  onRender();
  return (
    <ul>
      {series.map((label) => (
        <li key={label}>
          <button type="button" onClick={() => onSelect(label)}>
            {label}
          </button>
        </li>
      ))}
    </ul>
  );
});

export function ChartPanel({
  points,
  buildSeries,
  onLegendRender,
}: {
  points: number[];
  buildSeries: (points: number[]) => string[];
  onLegendRender: () => void;
}) {
  const [theme, setTheme] = useState("light");
  const [picked, setPicked] = useState<string | null>(null);

  // The expensive part, and the identity the memoized legend compares against
  // - one useMemo doing both jobs at once.
  const series = useMemo(() => buildSeries(points), [points, buildSeries]);

  // Nothing to read, so nothing to depend on.
  const onSelect = useCallback((label: string) => setPicked(label), []);

  return (
    <>
      <p role="status">Theme: {theme}</p>
      <button
        type="button"
        onClick={() => setTheme((current) => (current === "light" ? "dark" : "light"))}
      >
        Switch theme
      </button>
      {picked !== null && <p>Picked: {picked}</p>}
      <Legend series={series} onSelect={onSelect} onRender={onLegendRender} />
    </>
  );
}

