// d22_render_performance / ex1 - reference solution.
import { useState, type ReactNode } from "react";

function HeavyPanel({ onRender }: { onRender: () => void }) {
  onRender();
  return <p>Panel contents</p>;
}

// The ticker no longer knows what it is wrapping. Its state changes, it
// re-renders, and `children` is the very same element object it was handed
// last time - so React has nothing to do with that subtree.
function Ticker({ children }: { children: ReactNode }) {
  const [ticks, setTicks] = useState(0);

  return (
    <>
      <p role="status">Ticks: {ticks}</p>
      <button type="button" onClick={() => setTicks((current) => current + 1)}>
        Tick
      </button>
      {children}
    </>
  );
}

export function TickerPage({ onPanelRender }: { onPanelRender: () => void }) {
  // The element is created here, in a component that has no state at all and
  // therefore never re-renders on its own.
  return (
    <Ticker>
      <HeavyPanel onRender={onPanelRender} />
    </Ticker>
  );
}

// d22_render_performance / ex2 - reference solution.
import { useState } from "react";

function ReportBody({ onRender }: { onRender: () => void }) {
  onRender();
  return <p>Quarterly report</p>;
}

// The flag now lives in the smallest component that needs it, so the renders
// it causes reach exactly as far as the thing it decides.
function HelpToggle() {
  const [showHelp, setShowHelp] = useState(false);

  return (
    <>
      <button type="button" onClick={() => setShowHelp((current) => !current)}>
        {showHelp ? "Hide help" : "Show help"}
      </button>
      {showHelp && <p>Read the manual</p>}
    </>
  );
}

export function HelpPanel({ onBodyRender }: { onBodyRender: () => void }) {
  // No state at all here now, so nothing makes this component render again -
  // and the report below is never disturbed.
  return (
    <>
      <HelpToggle />
      <ReportBody onRender={onBodyRender} />
    </>
  );
}

// d22_render_performance / ex3 - reference solution.
import { useState } from "react";

export type ExpandableRow = { id: string; label: string };

function RowBody({ row, onRender }: { row: ExpandableRow; onRender: (id: string) => void }) {
  onRender(row.id);
  return <p>{row.label} details</p>;
}

function Row({
  row,
  onBodyRender,
}: {
  row: ExpandableRow;
  onBodyRender: (id: string) => void;
}) {
  const [open, setOpen] = useState(false);

  return (
    <li>
      <button type="button" onClick={() => setOpen((current) => !current)}>
        {open ? "Close" : "Open"} {row.label}
      </button>
      {/* Not rendered and hidden - not rendered at all. The cheapest render is
          the one that never happens, and a closed row has nothing worth
          building: no DOM, no effects, no requests. */}
      {open && <RowBody row={row} onRender={onBodyRender} />}
    </li>
  );
}

export function ExpandableRows({
  rows,
  onBodyRender,
}: {
  rows: ExpandableRow[];
  onBodyRender: (id: string) => void;
}) {
  return (
    <ul>
      {rows.map((row) => (
        <Row key={row.id} row={row} onBodyRender={onBodyRender} />
      ))}
    </ul>
  );
}

// d22_render_performance / ex4 - reference solution.
import { useState } from "react";

function Row({ item, onRender }: { item: string; onRender: () => void }) {
  onRender();
  return <li>{item}</li>;
}

export function WindowedRows({
  items,
  windowSize,
  onRowRender,
}: {
  items: string[];
  windowSize: number;
  onRowRender: () => void;
}) {
  const [shown, setShown] = useState(windowSize);

  // The number of rows on screen is a decision this component gets to make.
  // No amount of memoizing a row makes rendering ninety-five invisible ones
  // free, because the work is the rendering itself.
  const visible = items.slice(0, shown);

  return (
    <>
      <p role="status">
        Showing {visible.length} of {items.length}
      </p>
      <ul>
        {visible.map((item) => (
          <Row key={item} item={item} onRender={onRowRender} />
        ))}
      </ul>
      <button type="button" onClick={() => setShown((current) => current + windowSize)}>
        Show more
      </button>
    </>
  );
}

// d22_render_performance / ex5 - reference solution.
import { useState } from "react";

export function SelectionBar({
  options,
  onRender,
}: {
  options: string[];
  onRender: () => void;
}) {
  onRender();
  // The choice is a name, so store a name. React compares the next state with
  // the current one using Object.is and does nothing at all when they match -
  // an object wrapper throws that away for no benefit.
  const [selected, setSelected] = useState(options[0]);

  return (
    <>
      <p role="status">Selected: {selected}</p>
      {options.map((option) => (
        <button key={option} type="button" onClick={() => setSelected(option)}>
          Pick {option}
        </button>
      ))}
    </>
  );
}

// d22_render_performance / ex6 - reference solution.
import { useState } from "react";

export function SessionPanel({
  readToken,
  onRender,
}: {
  readToken: () => string;
  onRender: () => void;
}) {
  onRender();
  // The token is available synchronously, so there is no reason for a render
  // in which it is missing. Passing the function - not calling it - means
  // React runs it once, before the first render, and never again.
  const [token] = useState(readToken);

  return <p role="status">Session {token}</p>;
}

// d22_render_performance / ex7 - reference solution.
import { useId, useState } from "react";

function LeftPanel({ onRender }: { onRender: () => void }) {
  onRender();
  return <p>Left panel</p>;
}

function RightPanel({ onRender }: { onRender: () => void }) {
  onRender();
  return <p>Right panel</p>;
}

// Each piece of state moves to the smallest component that needs it, together
// with everything that displays it.
function TickCounter() {
  const [ticks, setTicks] = useState(0);
  return (
    <>
      <p role="status">Ticks: {ticks}</p>
      <button type="button" onClick={() => setTicks((current) => current + 1)}>
        Tick
      </button>
    </>
  );
}

function SearchBox() {
  const id = useId();
  const [search, setSearch] = useState("");
  return (
    <>
      <label htmlFor={id}>Search</label>
      <input id={id} value={search} onChange={(event) => setSearch(event.target.value)} />
      <p>Searching for {search}</p>
    </>
  );
}

export function DashboardShell({
  onLeftRender,
  onRightRender,
}: {
  onLeftRender: () => void;
  onRightRender: () => void;
}) {
  // Nothing left here that can change, so nothing left that can cause a
  // render - which is a stronger guarantee than any memo, and one that cannot
  // rot when somebody adds a prop later.
  return (
    <>
      <TickCounter />
      <SearchBox />
      <LeftPanel onRender={onLeftRender} />
      <RightPanel onRender={onRightRender} />
    </>
  );
}

// d22_render_performance / ex8 - reference solution.
import { memo, useCallback, useId, useMemo, useState } from "react";

export type TableRow = { id: string; name: string };

// Memoized, so a render of the table is not automatically a render of every
// row - which is only worth anything because all four props below are stable.
const Row = memo(function Row({
  row,
  starred,
  onStar,
  onRender,
}: {
  row: TableRow;
  starred: boolean;
  onStar: (id: string) => void;
  onRender: (id: string) => void;
}) {
  onRender(row.id);
  return (
    <li>
      <span>
        {row.name}
        {starred ? " *" : ""}
      </span>
      <button type="button" onClick={() => onStar(row.id)}>
        Star {row.name}
      </button>
    </li>
  );
});

export function SortableTable({
  rows,
  onSort,
  onRowRender,
}: {
  rows: TableRow[];
  onSort: () => void;
  onRowRender: (id: string) => void;
}) {
  const id = useId();
  const [query, setQuery] = useState("");
  const [descending, setDescending] = useState(false);
  const [starred, setStarred] = useState<Record<string, boolean>>({});

  // Two steps, two dependency lists. Sorting depends on the rows and the
  // direction; filtering depends on the sorted rows and the query. Typing
  // therefore cannot cost a sort.
  const sorted = useMemo(() => {
    onSort();
    return [...rows].sort((left, right) =>
      descending ? right.name.localeCompare(left.name) : left.name.localeCompare(right.name),
    );
  }, [rows, descending, onSort]);

  const visible = useMemo(
    () => sorted.filter((row) => row.name.toLowerCase().includes(query.toLowerCase())),
    [sorted, query],
  );

  // One handler for every row, and the row says which row it is.
  const star = useCallback((rowId: string) => {
    setStarred((current) => ({ ...current, [rowId]: !current[rowId] }));
  }, []);

  return (
    <>
      <label htmlFor={id}>Filter</label>
      <input id={id} value={query} onChange={(event) => setQuery(event.target.value)} />
      <button type="button" onClick={() => setDescending((current) => !current)}>
        Sort by name
      </button>
      <ul>
        {visible.map((row) => (
          <Row
            key={row.id}
            row={row}
            starred={starred[row.id] ?? false}
            onStar={star}
            onRender={onRowRender}
          />
        ))}
      </ul>
    </>
  );
}

