// d23_component_patterns / ex1 - reference solution.
import type { ReactNode } from "react";

export function Callout({
  tone,
  title,
  children,
}: {
  tone: "info" | "danger";
  title: string;
  children?: ReactNode;
}) {
  return (
    <div role={tone === "danger" ? "alert" : "status"}>
      {/* A slot, because a title is one specific thing in one specific place */}
      <h3>{title}</h3>
      {/* and children, because the body is whatever the caller needs it to be */}
      {children}
    </div>
  );
}

// d23_component_patterns / ex2 - reference solution.
import { useCallback, useId, useState } from "react";

// The behaviour, with nothing about questions or answers in it. Any component
// that needs "a thing that is open or closed" can call this and get its own.
export function useDisclosure(initial = false) {
  const [open, setOpen] = useState(initial);

  const toggle = useCallback(() => setOpen((current) => !current), []);
  const close = useCallback(() => setOpen(false), []);

  return { open, toggle, close };
}

export function FaqItem({ question, answer }: { question: string; answer: string }) {
  const id = useId();
  const { open, toggle } = useDisclosure();

  return (
    <>
      {/* aria-expanded is how a button says what it did, and it is the one
          part of this pattern people leave out. */}
      <button type="button" aria-expanded={open} aria-controls={id} onClick={toggle}>
        {question}
      </button>
      {open && <p id={id}>{answer}</p>}
    </>
  );
}

// d23_component_patterns / ex3 - reference solution.
import { createContext, useContext, useState, type ReactNode } from "react";

// The whole point of a compound component: the parts are written by the caller
// in whatever arrangement they like, and they find each other through a
// context rather than through props nobody wants to pass.
const TabsContext = createContext<{
  selected: string;
  select: (id: string) => void;
} | null>(null);

function useTabs() {
  const value = useContext(TabsContext);
  if (value === null) throw new Error("Tabs parts must be used inside <Tabs>");
  return value;
}

export function Tabs({ defaultTab, children }: { defaultTab: string; children: ReactNode }) {
  const [selected, setSelected] = useState(defaultTab);
  return (
    <TabsContext.Provider value={{ selected, select: setSelected }}>
      <div>{children}</div>
    </TabsContext.Provider>
  );
}

function List({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div role="tablist" aria-label={label}>
      {children}
    </div>
  );
}

function Tab({ id, children }: { id: string; children: ReactNode }) {
  const { selected, select } = useTabs();
  return (
    <button
      type="button"
      role="tab"
      aria-selected={selected === id}
      onClick={() => select(id)}
    >
      {children}
    </button>
  );
}

function Panel({ id, children }: { id: string; children: ReactNode }) {
  const { selected } = useTabs();
  // Only the panel that is showing exists at all.
  if (selected !== id) return null;
  return <div role="tabpanel">{children}</div>;
}

Tabs.List = List;
Tabs.Tab = Tab;
Tabs.Panel = Panel;

// d23_component_patterns / ex4 - reference solution.
import { createContext, useContext, useId, type ReactNode } from "react";

// The card generates an id and the title takes it. Nothing about that is
// visible to the caller, which is the whole reason to build it this way.
const CardContext = createContext<string | null>(null);

export function ProductCard({ children }: { children: ReactNode }) {
  const titleId = useId();
  return (
    <CardContext.Provider value={titleId}>
      {/* The name of this article is whatever the title inside it says. */}
      <article aria-labelledby={titleId}>{children}</article>
    </CardContext.Provider>
  );
}

function Media({ children }: { children: ReactNode }) {
  return <div>{children}</div>;
}

function Body({ children }: { children: ReactNode }) {
  return <div>{children}</div>;
}

function Title({ children }: { children: ReactNode }) {
  const titleId = useContext(CardContext);
  if (titleId === null) throw new Error("ProductCard.Title must be used inside <ProductCard>");
  return <h3 id={titleId}>{children}</h3>;
}

function Actions({ children }: { children: ReactNode }) {
  return <footer>{children}</footer>;
}

ProductCard.Media = Media;
ProductCard.Body = Body;
ProductCard.Title = Title;
ProductCard.Actions = Actions;

// d23_component_patterns / ex5 - reference solution.
import { useId, type ReactNode } from "react";

export type HintedFieldParts = { id: string; describedBy: string | undefined };

export function HintedField({
  label,
  hint,
  children,
}: {
  label: string;
  hint?: string;
  children: (parts: HintedFieldParts) => ReactNode;
}) {
  // Unique per instance, so two fields on one page cannot steal each other's
  // label - which is exactly what a pair of hard-coded ids does.
  const id = useId();
  const hintId = `${id}-hint`;

  return (
    <p>
      <label htmlFor={id}>{label}</label>
      {/* The caller writes the control; the field tells it what to be called.
          A describedBy of undefined means React omits the attribute, which is
          the only correct thing to do when there is no hint to point at. */}
      {children({ id, describedBy: hint === undefined ? undefined : hintId })}
      {hint !== undefined && <span id={hintId}>{hint}</span>}
    </p>
  );
}

// d23_component_patterns / ex6 - reference solution.
import { createContext, useContext, type ReactNode } from "react";

// A default of false means a button used outside any toolbar still works,
// which keeps the component usable on its own.
const ToolbarDisabledContext = createContext(false);

export function Toolbar({
  label,
  disabled = false,
  children,
}: {
  label: string;
  disabled?: boolean;
  children: ReactNode;
}) {
  return (
    <ToolbarDisabledContext.Provider value={disabled}>
      <div role="toolbar" aria-label={label}>
        {children}
      </div>
    </ToolbarDisabledContext.Provider>
  );
}

export function ToolbarButton({
  onClick,
  disabled = false,
  children,
}: {
  onClick: () => void;
  disabled?: boolean;
  children: ReactNode;
}) {
  const toolbarDisabled = useContext(ToolbarDisabledContext);

  return (
    <button
      type="button"
      // Either reason is reason enough: the toolbar said so, or this button
      // did. Neither can override the other into being enabled.
      disabled={toolbarDisabled || disabled}
      onClick={onClick}
    >
      {children}
    </button>
  );
}

// d23_component_patterns / ex7 - reference solution.
import { useState, type ReactNode } from "react";

export function PickerList({
  items,
  renderItem,
  empty,
}: {
  items: string[];
  renderItem: (item: string, picked: boolean) => ReactNode;
  empty?: ReactNode;
}) {
  const [picked, setPicked] = useState<string | null>(null);

  // An empty list is a state with something to say, and the caller is the one
  // who knows what. Rendering an empty <ul> says nothing to anybody.
  if (items.length === 0) return <>{empty}</>;

  return (
    <ul>
      {items.map((item) => (
        <li key={item}>
          <button type="button" onClick={() => setPicked(item)}>
            {/* The list owns which row is picked; the caller owns what picked
                looks like. That division only works if the answer is handed
                over at the moment the markup is asked for. */}
            {renderItem(item, item === picked)}
          </button>
        </li>
      ))}
    </ul>
  );
}

// d23_component_patterns / ex8 - reference solution.
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
  type RefObject,
} from "react";

type PopoverValue = {
  open: boolean;
  contentId: string;
  toggle: () => void;
  close: () => void;
  triggerRef: RefObject<HTMLButtonElement | null>;
};

const PopoverContext = createContext<PopoverValue | null>(null);

function usePopover(): PopoverValue {
  const value = useContext(PopoverContext);
  if (value === null) throw new Error("Popover parts must be used inside <Popover>");
  return value;
}

export function Popover({ children }: { children: ReactNode }) {
  // The id lives here because it is the one component that contains both the
  // trigger that names it and the content that answers to it.
  const contentId = useId();
  const [open, setOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);

  const toggle = useCallback(() => setOpen((current) => !current), []);

  const close = useCallback(() => {
    setOpen(false);
    // The element that had focus is about to be removed, so somebody has to
    // catch it - and the trigger is where the user was before they opened it.
    triggerRef.current?.focus();
  }, []);

  const value = useMemo<PopoverValue>(
    () => ({ open, contentId, toggle, close, triggerRef }),
    [open, contentId, toggle, close],
  );

  return <PopoverContext.Provider value={value}>{children}</PopoverContext.Provider>;
}

function Trigger({ children }: { children: ReactNode }) {
  const { open, contentId, toggle, triggerRef } = usePopover();
  return (
    <button
      type="button"
      ref={triggerRef}
      aria-expanded={open}
      // Only while the content exists: a reference to a missing id is a dead
      // link as far as a screen reader is concerned.
      aria-controls={open ? contentId : undefined}
      onClick={toggle}
    >
      {children}
    </button>
  );
}

function Content({ children }: { children: ReactNode }) {
  const { open, contentId, close } = usePopover();
  const box = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const first = box.current?.querySelector<HTMLElement>(
      "button, [href], input, select, textarea, [tabindex]",
    );
    first?.focus();
  }, [open]);

  if (!open) return null;

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key === "Escape") close();
  }

  return (
    <div id={contentId} ref={box} onKeyDown={handleKeyDown}>
      {children}
    </div>
  );
}

Popover.Trigger = Trigger;
Popover.Content = Content;

