// d24_mixed_gauntlet / ex1 - reference solution.
import { useId, useState } from "react";

export function VoucherBox({ onRedeem }: { onRedeem: (code: string) => void }) {
  const id = useId();
  // What the user typed, unchanged - rewriting it under their cursor is the
  // fastest way to make a controlled input feel broken.
  const [typed, setTyped] = useState("");

  // What the code actually is. Derived during render, so it can never be out
  // of step with the box, and computed once for everything that needs it.
  const code = typed.trim().toUpperCase();
  const ready = code.length >= 5;

  return (
    <>
      <label htmlFor={id}>Voucher</label>
      <input id={id} value={typed} onChange={(event) => setTyped(event.target.value)} />
      <p role="status">{ready ? "Ready" : "Keep typing"}</p>
      <button type="button" disabled={!ready} onClick={() => onRedeem(code)}>
        Redeem
      </button>
    </>
  );
}

// d24_mixed_gauntlet / ex2 - reference solution.
import { useState } from "react";

export function RosterBoard({ people }: { people: string[] }) {
  // One lead, so one value - not a flag per person that something has to
  // remember to clear. And it is the only thing worth storing: the order on
  // screen follows from it.
  const [lead, setLead] = useState<string | null>(null);

  // Derived during render, so a changed roster is reflected immediately and
  // nothing can drift out of step with the prop.
  const order =
    lead === null ? people : [lead, ...people.filter((person) => person !== lead)];

  if (people.length === 0) {
    // An empty list is a state with something to say.
    return <p role="status">Nobody on the roster</p>;
  }

  return (
    <>
      <ul>
        {order.map((person) => (
          // Keyed by the person, so React keeps each row's identity when the
          // order changes rather than rewriting them all in place.
          <li key={person}>
            <span>{person === lead ? `${person} (lead)` : person}</span>
            <button type="button" onClick={() => setLead(person)}>
              Promote {person}
            </button>
          </li>
        ))}
      </ul>
      <button type="button" onClick={() => setLead(null)}>
        Reset
      </button>
    </>
  );
}

// d24_mixed_gauntlet / ex3 - reference solution.
import { useEffect, useRef, useState } from "react";

export function IdleWatcher({
  timeoutMs,
  onIdle,
}: {
  timeoutMs: number;
  onIdle: () => void;
}) {
  const [idle, setIdle] = useState(false);
  // A counter, not a timestamp: all this needs to say is "something happened
  // again", which is exactly what a changed dependency means.
  const [activity, setActivity] = useState(0);

  // The newest callback, so restarting the clock does not depend on the parent
  // keeping its function identity stable.
  const latest = useRef(onIdle);
  useEffect(() => {
    latest.current = onIdle;
  });

  useEffect(() => {
    // Nothing to count once it has gone idle - and this is what leaves no
    // timer behind at the end.
    if (idle) return;

    const id = setTimeout(() => {
      setIdle(true);
      latest.current();
    }, timeoutMs);

    // Runs before every restart and once on the way out, which is the whole
    // of "the clock starts again when something happens".
    return () => clearTimeout(id);
  }, [activity, timeoutMs, idle]);

  return (
    <>
      <p role="status">{idle ? "Idle" : "Active"}</p>
      <button
        type="button"
        onClick={() => {
          setIdle(false);
          setActivity((current) => current + 1);
        }}
      >
        Activity
      </button>
    </>
  );
}

// d24_mixed_gauntlet / ex4 - reference solution.
import { createContext, useContext, useEffect, useState, type ReactNode } from "react";

const SessionContext = createContext<string | null>(null);

export function SessionProvider({
  userId,
  children,
}: {
  userId: string;
  children: ReactNode;
}) {
  return <SessionContext.Provider value={userId}>{children}</SessionContext.Provider>;
}

export type SessionProfile = { name: string };

export function ProfilePane({
  loadProfile,
}: {
  loadProfile: (userId: string) => Promise<SessionProfile>;
}) {
  const userId = useContext(SessionContext);
  const [profile, setProfile] = useState<SessionProfile | null>(null);

  useEffect(() => {
    if (userId === null) return;

    // One flag per run of the effect. The cleanup below flips the one
    // belonging to the session it is retiring, and nothing else.
    let current = true;
    setProfile(null);

    loadProfile(userId).then((next) => {
      if (!current) return;
      setProfile(next);
    });

    return () => {
      current = false;
    };
  }, [userId, loadProfile]);

  // Every hook has been called by the time this runs, which is what makes an
  // early return here legal.
  if (userId === null) {
    throw new Error("ProfilePane must be used inside a SessionProvider");
  }
  if (profile === null) {
    return <p role="status">Loading profile</p>;
  }
  return <h2>{profile.name}</h2>;
}

// d24_mixed_gauntlet / ex5 - reference solution.
import { useCallback, useReducer } from "react";

export type CartProduct = { id: string; name: string; price: number };

export type Line = CartProduct & { qty: number };

type CartAction = { type: "added"; product: CartProduct } | { type: "removed"; id: string };

function cartReducer(lines: Line[], action: CartAction): Line[] {
  switch (action.type) {
    case "added": {
      const existing = lines.find((line) => line.id === action.product.id);
      if (existing === undefined) return [...lines, { ...action.product, qty: 1 }];
      return lines.map((line) =>
        line.id === action.product.id ? { ...line, qty: line.qty + 1 } : line,
      );
    }
    case "removed":
      return lines
        .map((line) => (line.id === action.id ? { ...line, qty: line.qty - 1 } : line))
        .filter((line) => line.qty > 0);
  }
}

export function useCart() {
  const [lines, dispatch] = useReducer(cartReducer, [] as Line[]);

  // Derived while rendering. Kept in state it would be a second copy of the
  // same fact, and every action ever added to the reducer would have to
  // remember to update it.
  const total = lines.reduce((sum, line) => sum + line.price * line.qty, 0);

  // `dispatch` is stable, so neither of these has anything to depend on - and
  // a hook that hands out new functions every render makes work for everybody
  // who consumes it.
  const add = useCallback((product: CartProduct) => dispatch({ type: "added", product }), []);
  const remove = useCallback((id: string) => dispatch({ type: "removed", id }), []);

  return { lines, total, add, remove };
}

export function CartPanel({ products }: { products: CartProduct[] }) {
  // The panel is only markup. Everything a cart is lives in the hook, which is
  // why the gate can test the cart without rendering anything at all.
  const { lines, total, add } = useCart();

  return (
    <>
      {products.map((product) => (
        <button key={product.id} type="button" onClick={() => add(product)}>
          Add {product.name}
        </button>
      ))}
      <ul>
        {lines.map((line) => (
          <li key={line.id}>
            {line.name} x{line.qty}
          </li>
        ))}
      </ul>
      <p role="status">Total: {total}</p>
    </>
  );
}

// d24_mixed_gauntlet / ex6 - reference solution.
import { useCallback, useEffect, useRef, useState } from "react";

type Toast = { id: number; message: string };

// One toast, one component, one effect - which is the only way each toast can
// have a clock of its own. The cleanup covers both dismissing it by hand and
// the whole queue going away.
function ToastRow({
  toast,
  autoDismissMs,
  onDismiss,
}: {
  toast: Toast;
  autoDismissMs: number;
  onDismiss: (id: number) => void;
}) {
  useEffect(() => {
    const timer = setTimeout(() => onDismiss(toast.id), autoDismissMs);
    return () => clearTimeout(timer);
  }, [toast.id, autoDismissMs, onDismiss]);

  return (
    <li>
      <span>{toast.message}</span>
      <button type="button" onClick={() => onDismiss(toast.id)}>
        Dismiss {toast.message}
      </button>
    </li>
  );
}

export function ToastQueue({ autoDismissMs }: { autoDismissMs: number }) {
  const [toasts, setToasts] = useState<Toast[]>([]);
  // Ids come from a counter that only ever goes up, so a number is never
  // reused by a toast that arrives after another has been dismissed.
  const nextId = useRef(1);

  // Stable, so the row's effect does not re-arm its timer on every render of
  // the queue - which would mean no toast ever expired.
  const dismiss = useCallback((id: number) => {
    setToasts((current) => current.filter((toast) => toast.id !== id));
  }, []);

  function notify() {
    const id = nextId.current;
    nextId.current += 1;
    setToasts((current) => [...current, { id, message: `Message ${id}` }]);
  }

  return (
    <>
      <button type="button" onClick={notify}>
        Notify
      </button>
      <div role="status">
        <ul>
          {toasts.map((toast) => (
            <ToastRow
              key={toast.id}
              toast={toast}
              autoDismissMs={autoDismissMs}
              onDismiss={dismiss}
            />
          ))}
        </ul>
      </div>
    </>
  );
}

// d24_mixed_gauntlet / ex7 - reference solution.
import { useEffect, useId, useState } from "react";

export function SearchWorkbench({
  search,
}: {
  search: (query: string) => Promise<string[]>;
}) {
  const id = useId();
  // What is in the box, and what has actually been asked. They are different
  // things, and separating them is what a debounce is.
  const [query, setQuery] = useState("");
  const [asked, setAsked] = useState("");
  const [results, setResults] = useState<string[] | null>(null);
  const [pending, setPending] = useState(false);

  useEffect(() => {
    if (query === "") return;

    const timer = setTimeout(() => setAsked(query), 300);
    // The cancellation *is* the debounce. Without it every keystroke still
    // sends a request, just 300ms later than it would have.
    return () => clearTimeout(timer);
  }, [query]);

  useEffect(() => {
    if (asked === "") return;

    // Debouncing makes the race rarer and cannot remove it: a slow answer to
    // an old question still arrives after a fast answer to a new one.
    let current = true;
    setPending(true);

    search(asked).then((next) => {
      if (!current) return;
      setResults(next);
      setPending(false);
    });

    return () => {
      current = false;
    };
  }, [asked, search]);

  const status = pending ? "Searching" : results === null ? "Idle" : `${results.length} results`;

  return (
    <>
      <label htmlFor={id}>Query</label>
      <input id={id} value={query} onChange={(event) => setQuery(event.target.value)} />
      <p role="status">{status}</p>
      <ul>
        {(results ?? []).map((result) => (
          <li key={result}>{result}</li>
        ))}
      </ul>
    </>
  );
}

// d24_mixed_gauntlet / ex8 - reference solution.
import {
  Children,
  createContext,
  isValidElement,
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";

type WizardValue = {
  index: number;
  total: number;
  next: () => void;
  back: () => void;
};

const WizardContext = createContext<WizardValue | null>(null);

function useWizard(): WizardValue {
  const value = useContext(WizardContext);
  if (value === null) throw new Error("Wizard parts must be used inside <Wizard>");
  return value;
}

export function Wizard({ children }: { children: ReactNode }) {
  const [index, setIndex] = useState(0);

  // Separate the steps from everything else the caller wrote, so the nav can
  // sit anywhere among them and only one step is ever rendered.
  const all = Children.toArray(children);
  const steps = all.filter((child) => isValidElement(child) && child.type === Step);
  const rest = all.filter((child) => !(isValidElement(child) && child.type === Step));

  const value: WizardValue = {
    index,
    total: steps.length,
    next: () => setIndex((current) => Math.min(current + 1, steps.length - 1)),
    back: () => setIndex((current) => Math.max(current - 1, 0)),
  };

  return (
    <WizardContext.Provider value={value}>
      <div>
        {/* Children.toArray gives each child a key, so moving to another step
            really unmounts this one and mounts that one - which is what makes
            the mount effect in Step fire again. */}
        {steps[index]}
        {rest}
      </div>
    </WizardContext.Provider>
  );
}

function Step({ title, children }: { title: string; children: ReactNode }) {
  const heading = useRef<HTMLHeadingElement>(null);

  // The step that was on screen has just been removed, taking the focused
  // element with it. Something has to catch the keyboard, and the heading of
  // what replaced it is the honest answer.
  useEffect(() => {
    heading.current?.focus();
  }, []);

  return (
    <section>
      {/* tabIndex -1 makes it focusable by script without putting it in the
          tab order. */}
      <h2 tabIndex={-1} ref={heading}>
        {title}
      </h2>
      {children}
    </section>
  );
}

function Nav() {
  const { index, total, next, back } = useWizard();

  return (
    <>
      <p role="status">
        Step {index + 1} of {total}
      </p>
      <button type="button" disabled={index === 0} onClick={back}>
        Back
      </button>
      <button type="button" disabled={index === total - 1} onClick={next}>
        Next
      </button>
    </>
  );
}

Wizard.Step = Step;
Wizard.Nav = Nav;

lessons.fullReadme:
# i1 — Interview concepts

The main course is behind you. This part is about being able to *say* what you
know, under time pressure, to somebody who is deciding whether to hire you.

Those are different skills. You can fix a stale closure and still fumble the
sentence that explains it. Interviewers are listening for the mechanism —
"the callback was created during one render and captured that render's
`count`" — and a candidate who says it plainly reads as senior even when the
code takes them two minutes.

So this lesson is mostly `reading.md`, which carries **a bank of 55 questions
with model answers**, grouped by topic, each tagged by how often it actually
gets asked:

| tag | meaning |
|---|---|
| ⭐⭐⭐ | expect it in most React interviews. Know it cold. |
| ⭐⭐ | common, especially for mid-level and above. |
| ⭐ | asked when the conversation goes deep, or by a specialist. |

Each answer is written the way a strong candidate would actually say it — three
to six sentences, one concrete example, and the **follow-up** the interviewer
will reach for next. Every question names the lesson that teaches it, so a
question you cannot answer turns straight into "redo `06_effects`".

The five graded exercises here are the concepts that can be checked in code:
four bugs of the kind interviewers put in front of you, and one code review.
Each one compiles and is wrong, and none of them takes more than a few lines to
fix — because the point is the diagnosis.

## How to use the question bank

Do not read it like a document. Work it like flashcards:

1. Open `reading.md` — `uv run dojo read react i1_interview_concepts` — and
   cover everything below a question.
2. **Say the answer out loud.** Not in your head. The gap between "I know this"
   and "I can say this" is the entire reason people fail interviews they were
   qualified for, and it only closes by talking.
3. Uncover, and compare. Did you name the mechanism, or only the fix? Did you
   have an example ready? Could you answer the follow-up?
4. Mark the ⭐⭐⭐ questions you fumbled and come back to them tomorrow. The
   review ladder does this for the exercises; do it yourself for the prose.

A pass through all 55 takes about an hour. A pass through the ⭐⭐⭐ subset
takes fifteen minutes, and is the thing to do the morning of an interview.

## Exercise 1 — the stale-closure counter

Edit `ex1/solution.tsx`.

> *"This counter is supposed to tick up every second. It stops at 1. Talk me
> through why, then fix it."*

Answer the "why" out loud before you edit anything — that is what is being
marked. Then make it count 3 after three seconds, and keep going.

```
uv run dojo test react i1_interview_concepts ex1
```

## Exercise 2 — index keys

Edit `ex2/solution.tsx`.

> *"Type something into the Zebra row, then hit Sort. Where did your text go,
> and why?"*

Each row has an uncontrolled text box. Sorting must not move what the user
typed into a different row.

```
uv run dojo test react i1_interview_concepts ex2
```

## Exercise 3 — controlled vs uncontrolled

Edit `ex3/solution.tsx`.

> *"Reset does nothing. React clearly knows the value — the character count is
> right. So who is deciding what the box displays?"*

After Reset, the field must be empty and the counter must read `0 characters`.

```
uv run dojo test react i1_interview_concepts ex3
```

## Exercise 4 — the effect that should not exist

Edit `ex4/solution.tsx`.

> *"What's wrong with this component? It works."*

It does work, and it renders twice for every change, showing `Total: 0` for a
frame. The gate counts renders and requires exactly one per change.

```
uv run dojo test react i1_interview_concepts ex4
```

## Review — read this effect back to me

`review1/solution.tsx`.

> *"Code review this for me. Anything you'd change?"*

There are two defects and they compound. The gate re-renders the component and
then unmounts it, checking how many times one keystroke fires the handler.

```
uv run dojo test react i1_interview_concepts review1
```

## The gate

This is the entire gate, `gate.test.tsx`:

<!-- GATE:BEGIN -->

```tsx
// Gate for react/i1_interview_concepts. Quoted verbatim in README.md.
//
// Four bugs an interviewer is likely to put in front of you, plus one for the
// review ladder. Each is a complete component that compiles and is wrong.
import { act, render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { afterEach, describe, expect, test, vi } from "vitest";

import { StaleCounter } from "./ex1/solution";
import { ReorderableList } from "./ex2/solution";
import { NicknameForm } from "./ex3/solution";
import { OrderSummary } from "./ex4/solution";
import { ShortcutListener } from "./review1/solution";

afterEach(() => {
  vi.useRealTimers();
});

describe("i1_interview_concepts", () => {
  test("ex1 - StaleCounter keeps counting past one", () => {
    vi.useFakeTimers();
    render(<StaleCounter />);

    act(() => {
      vi.advanceTimersByTime(3000);
    });
    expect(
      screen.getByRole("status"),
      "three seconds, three ticks, and it reads 1. The function handed to " +
        "setInterval was created during the first render and captured count as " +
        "0 forever, so every tick sets it to 0 + 1. Say that sentence out loud - " +
        "it is the answer they are listening for (README ex1)",
    ).toHaveTextContent("3");

    act(() => {
      vi.advanceTimersByTime(2000);
    });
    expect(screen.getByRole("status"), "and it keeps going").toHaveTextContent("5");
  });

  test("ex2 - ReorderableList keeps each row attached to its own item", async () => {
    const user = userEvent.setup();
    render(
      <ReorderableList
        initialItems={[
          { id: "z", label: "Zebra" },
          { id: "a", label: "Apple" },
          { id: "m", label: "Mango" },
        ]}
      />,
    );

    await user.type(screen.getByLabelText("Zebra"), "notes");
    await user.click(screen.getByRole("button", { name: "Sort A-Z" }));

    expect(
      screen.queryAllByRole("textbox").length,
      "sorting must not add or drop rows",
    ).toBe(3);
    expect(
      screen.getByLabelText("Zebra"),
      "the text you typed is now in somebody else's box. The list is keyed by " +
        "position, so React thinks the row that used to be first is the same " +
        "row and reuses its DOM node - key by identity (README ex2)",
    ).toHaveValue("notes");
    expect(
      screen.getByLabelText("Apple"),
      "and the row that moved into first place must still be empty",
    ).toHaveValue("");
  }, 20000);

  test("ex3 - NicknameForm can actually be reset", async () => {
    const user = userEvent.setup();
    const onSave = vi.fn();
    render(<NicknameForm onSave={onSave} />);

    await user.type(screen.getByLabelText("Nickname"), "ada");
    expect(screen.getByRole("status"), "the counter follows the field").toHaveTextContent(
      "3 characters",
    );

    await user.click(screen.getByRole("button", { name: "Save" }));
    expect(onSave, "Save hands over what is in the field").toHaveBeenCalledWith("ada");

    await user.click(screen.getByRole("button", { name: "Reset" }));
    expect(
      screen.getByLabelText("Nickname"),
      "Reset emptied the state and the box still shows ada. defaultValue is " +
        "only read once, when the DOM node is created - after that the browser " +
        "owns the value and React cannot put it back (README ex3)",
    ).toHaveValue("");
    expect(screen.getByRole("status"), "and the counter agrees").toHaveTextContent(
      "0 characters",
    );
  }, 20000);

  test("ex4 - OrderSummary computes the total without a second render", () => {
    const onRender = vi.fn();
    const items = [
      { name: "Mug", price: 12 },
      { name: "Poster", price: 18 },
    ];

    const { rerender } = render(<OrderSummary items={items} onRender={onRender} />);

    expect(screen.getByRole("status"), "the total is the sum of the prices").toHaveTextContent(
      "Total: 30",
    );
    expect(
      onRender,
      "rendering this component twice means the user saw Total: 0 first. The " +
        "total is not state - it is something you can work out from the items " +
        "you were given, during the render that needs it (README ex4)",
    ).toHaveBeenCalledTimes(1);

    rerender(<OrderSummary items={[{ name: "Pen", price: 4 }]} onRender={onRender} />);
    expect(screen.getByRole("status"), "new items, new total").toHaveTextContent("Total: 4");
    expect(onRender, "and still one render per change").toHaveBeenCalledTimes(2);
  });

  test("review1 - ShortcutListener subscribes once and stops when it leaves", async () => {
    const user = userEvent.setup();
    const onSave = vi.fn();
    const { rerender, unmount } = render(<ShortcutListener onSave={onSave} />);

    await user.keyboard("s");
    expect(onSave, "pressing s saves").toHaveBeenCalledTimes(1);

    rerender(<ShortcutListener onSave={onSave} />);
    await user.keyboard("s");
    expect(
      onSave,
      "one keystroke fired the handler twice, so the re-render added a second " +
        "listener next to the first. An effect with no dependency array runs " +
        "after every render, and one with no cleanup never takes anything back",
    ).toHaveBeenCalledTimes(2);

    unmount();
    await user.keyboard("s");
    expect(
      onSave,
      "and a component that is gone must not still be listening",
    ).toHaveBeenCalledTimes(2);
  }, 20000);
});
```

<!-- GATE:END -->

In plain English:

- **ex1** uses fake timers to move three seconds instantly and requires the
  display to read `3`, then two more and requires `5`.
- **ex2** types into the box labelled `Zebra`, sorts, and asks the DOM for "the
  box labelled Zebra" again — with index keys, that is a different node.
- **ex3** types, saves, resets, and checks both the field and the counter.
- **ex4** counts renders: one for the initial mount, one more for a prop change,
  and no extras.
- **review1** presses `s`, re-renders, presses `s` again and requires exactly
  one more call (not two), then unmounts and requires none.

## The teaching point

Interviews reward *narration*. When you are handed a broken component, the
sequence that scores is: say what you observe, say what you think is causing
it, say how you would confirm, then fix. Silence while you type reads as
guessing, even when you are right.

The five bugs here were chosen because each has a one-line fix and a
three-sentence explanation, and the explanation is worth far more than the fix.
Anyone can memorise "use the updater form". The candidate who gets the offer is
the one who says *why* the closure was stale, and what the alternative fix would
have cost.

Next: **i2_interview_drills**, where you build things from scratch against a
clock.

<!-- spaced-retrieval:v1 -->
## Ten-pass spaced repetition

Use this ladder after completing **i1 — Interview concepts**. Each pass changes the retrieval
task so repetition strengthens recall instead of becoming answer recognition.
Do the named exercise from a blank starting point whenever practical, and only
open its hints after recording your first attempt.

| Pass | When | Practice target | Retrieval task |
|---:|---:|---|---|
| 1 | now | `ex1` | Close the notes and state the central rule in one precise sentence. |
| 2 | 3 days | `ex2` | Rebuild the smallest valid example from memory, then explain each part. |
| 3 | 7 days | `ex3` | Predict the result or behavior before running anything; reconcile surprises. |
| 4 | 21 days | `ex4` | Solve from a blank file and name the first tempting mistake you avoided. |
| 5 | 60 days | `review1` | Contrast this technique with its nearest alternative and choose between them. |
| 6 | 120 days | `ex1` | Add one realistic constraint and adapt the solution without consulting notes. |
| 7 | 240 days | `ex2` | Debug a deliberately broken version; explain the evidence before the repair. |
| 8 | 1 year | `ex3` | Teach the idea aloud in two minutes, including one boundary case. |
| 9 | 18 months | `ex4` | Transfer the pattern to a new domain and verify the result with the gate. |
| 10 | 3 years | `review1` | Complete a cold, timed solution and write the rule you want to retain long-term. |

A failed pass is useful evidence: return to pass 1 after three days. A clean
pass advances to the next interval. After pass 10, revisit the skill every
three years or whenever real work exposes a weak edge case.

