// i1_interview_concepts / ex1 - reference solution.
import { useEffect, useState } from "react";

export function StaleCounter() {
  const [count, setCount] = useState(0);

  useEffect(() => {
    const id = setInterval(() => {
      setCount((previous) => previous + 1);
    }, 1000);

    return () => clearInterval(id);
  }, []);

  return <output>{count}</output>;
}

// i1_interview_concepts / ex2 - reference solution.
import { useState } from "react";

type Item = { id: string; label: string };

export function ReorderableList({ initialItems }: { initialItems: Item[] }) {
  const [items, setItems] = useState(initialItems);

  function sort() {
    setItems((previous) => [...previous].sort((a, b) => a.label.localeCompare(b.label)));
  }

  return (
    <>
      <button type="button" onClick={sort}>
        Sort A-Z
      </button>
      <ul>
        {items.map((item) => (
          <li key={item.id}>
            <label htmlFor={item.id}>{item.label}</label>
            <input id={item.id} defaultValue="" />
          </li>
        ))}
      </ul>
    </>
  );
}

// i1_interview_concepts / ex3 - reference solution.
import { useState } from "react";

export function NicknameForm({ onSave }: { onSave: (nickname: string) => void }) {
  const [nickname, setNickname] = useState("");

  return (
    <>
      <label htmlFor="nickname">Nickname</label>
      <input
        id="nickname"
        value={nickname}
        onChange={(event) => setNickname(event.target.value)}
      />
      <output>{nickname.length} characters</output>
      <button type="button" onClick={() => onSave(nickname)}>
        Save
      </button>
      <button type="button" onClick={() => setNickname("")}>
        Reset
      </button>
    </>
  );
}

// i1_interview_concepts / ex4 - reference solution.

type Item = { name: string; price: number };

export function OrderSummary({
  items,
  onRender,
}: {
  items: Item[];
  onRender: () => void;
}) {
  onRender();

  const total = items.reduce((sum, item) => sum + item.price, 0);

  return <output>Total: {total}</output>;
}

// i1_interview_concepts / review1 - reference solution.
import { useEffect } from "react";

export function ShortcutListener({ onSave }: { onSave: () => void }) {
  useEffect(() => {
    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "s") {
        onSave();
      }
    }

    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [onSave]);

  return <p>Press s to save</p>;
}

