// i3_interview_rapidfire / ex1 - reference solution.
import { useState } from "react";

type Player = { id: string; name: string };

function PlayerRow({ player }: { player: Player }) {
  const [score, setScore] = useState(0);

  return (
    <li>
      <span>
        {player.name}: {score}
      </span>
      <button type="button" onClick={() => setScore((previous) => previous + 1)}>
        Point for {player.name}
      </button>
    </li>
  );
}

export function ScoreBoard({
  initialPlayers,
  newcomer,
}: {
  initialPlayers: Player[];
  newcomer: Player;
}) {
  const [players, setPlayers] = useState(initialPlayers);

  return (
    <>
      <button type="button" onClick={() => setPlayers((previous) => [newcomer, ...previous])}>
        Add player to front
      </button>
      <ul>
        {players.map((player) => (
          <PlayerRow key={player.id} player={player} />
        ))}
      </ul>
    </>
  );
}

// i3_interview_rapidfire / ex2 - reference solution.
import { useEffect } from "react";

export function ChannelIndicator({
  channel,
  label,
  onSubscribe,
  onUnsubscribe,
}: {
  channel: string;
  label: string;
  onSubscribe: (channel: string) => void;
  onUnsubscribe: (channel: string) => void;
}) {
  useEffect(() => {
    onSubscribe(channel);
    return () => {
      onUnsubscribe(channel);
    };
  }, [channel, onSubscribe, onUnsubscribe]);

  return <p>{label}</p>;
}

// i3_interview_rapidfire / ex3 - reference solution.
import { useState } from "react";

export function TripleBump({ onRender }: { onRender: () => void }) {
  const [count, setCount] = useState(0);

  onRender();

  function addThree() {
    setCount((previous) => previous + 1);
    setCount((previous) => previous + 1);
    setCount((previous) => previous + 1);
  }

  return (
    <>
      <output>{count}</output>
      <button type="button" onClick={addThree}>
        Add three
      </button>
    </>
  );
}

// i3_interview_rapidfire / ex4 - reference solution.
import { memo, useState } from "react";

const Body = memo(function Body({
  style,
  onBodyRender,
}: {
  style: { padding: number };
  onBodyRender: () => void;
}) {
  onBodyRender();
  return <p style={style}>Body</p>;
});

// Built once, for the module, so its identity never changes.
const BODY_STYLE = { padding: 8 };

export function Panel({ onBodyRender }: { onBodyRender: () => void }) {
  const [open, setOpen] = useState(false);

  return (
    <>
      <button type="button" onClick={() => setOpen((previous) => !previous)}>
        Toggle
      </button>
      <output>{open ? "open" : "closed"}</output>
      <Body style={BODY_STYLE} onBodyRender={onBodyRender} />
    </>
  );
}

// i3_interview_rapidfire / review1 - reference solution.

type Message = { id: string; subject: string };

export function NotificationBell({
  unread,
  messages,
}: {
  unread: number;
  messages: Message[];
}) {
  if (messages.length === 0) {
    return <p>You are all caught up</p>;
  }

  return (
    <>
      {unread > 0 && <span>{unread} new</span>}
      <ul>
        {messages.map((message) => (
          <li key={message.id}>{message.subject}</li>
        ))}
      </ul>
    </>
  );
}
